window.__castellumScenes&&window.__castellumScenes("B1",{"roles":{"toi":{"fr":"Toi","it":"Tu","es":"Tú","pt":"Tu","en":"You","de":"Du","nl":"Jij","ary":"Nta"},"voisine":{"fr":"La voisine","it":"La vicina","es":"La vecina","pt":"A vizinha","en":"The neighbour","de":"Die Nachbarin","nl":"De buurvrouw","ary":"J-jara"},"ami":{"fr":"Ton ami","it":"Il tuo amico","es":"Tu amigo","pt":"O teu amigo","en":"Your friend","de":"Dein Freund","nl":"Je vriend","ary":"Sa7bek"},"amie":{"fr":"Ton amie","it":"La tua amica","es":"Tu amiga","pt":"A tua amiga","en":"Your friend","de":"Deine Freundin","nl":"Je vriendin","ary":"Sa7btek"},"enfant":{"fr":"La petite fille","it":"La bambina","es":"La niña","pt":"A menina","en":"The little girl","de":"Das Mädchen","nl":"Het meisje","ary":"L-bent s-sghira"},"coach":{"fr":"Le coach","it":"L'allenatore","es":"El entrenador","pt":"O treinador","en":"The coach","de":"Der Trainer","nl":"De trainer","ary":"L-coach"},"soeur":{"fr":"Ta sœur","it":"Tua sorella","es":"Tu hermana","pt":"A tua irmã","en":"Your sister","de":"Deine Schwester","nl":"Je zus","ary":"Khtek"},"coloc":{"fr":"Ta colocataire","it":"La tua coinquilina","es":"Tu compañera de piso","pt":"A tua colega de casa","en":"Your flatmate","de":"Deine Mitbewohnerin","nl":"Je huisgenote","ary":"Lli saknin m3ak"},"recruteuse":{"fr":"La recruteuse","it":"La selezionatrice","es":"La entrevistadora","pt":"A recrutadora","en":"The interviewer","de":"Die Personalerin","nl":"De recruiter","ary":"L-mas2oula 3la t-tawdif"},"agentvol":{"fr":"L'agent de la compagnie","it":"L'addetto della compagnia","es":"El agente de la aerolínea","pt":"O funcionário da companhia","en":"The airline agent","de":"Der Mitarbeiter der Fluggesellschaft","nl":"De medewerker van de luchtvaartmaatschappij","ary":"L-mouwazzaf d ch-charika"},"conseillere":{"fr":"La conseillère","it":"La consulente","es":"La asesora","pt":"A gestora de conta","en":"The bank adviser","de":"Die Bankberaterin","nl":"De bankadviseur","ary":"L-moustachara d l-banka"},"garagiste":{"fr":"Le garagiste","it":"Il meccanico","es":"El mecánico","pt":"O mecânico","en":"The mechanic","de":"Der Mechaniker","nl":"De monteur","ary":"L-mikanisyan"},"veterinaire":{"fr":"La vétérinaire","it":"La veterinaria","es":"La veterinaria","pt":"A veterinária","en":"The vet","de":"Die Tierärztin","nl":"De dierenarts","ary":"T-tbiba d l-7ayawanat"},"guichetier":{"fr":"Le guichetier","it":"L'impiegato","es":"El empleado","pt":"O funcionário","en":"The counter clerk","de":"Der Schalterbeamte","nl":"De loketmedewerker","ary":"L-mouwazzaf f l-guichet"},"patron":{"fr":"Le patron","it":"Il titolare","es":"El jefe","pt":"O patrão","en":"The boss","de":"Der Chef","nl":"De baas","ary":"L-patron"},"pere":{"fr":"Ton père","it":"Tuo padre","es":"Tu padre","pt":"O teu pai","en":"Your dad","de":"Dein Vater","nl":"Je vader","ary":"Bbak"},"grandpere":{"fr":"Ton grand-père","it":"Tuo nonno","es":"Tu abuelo","pt":"O teu avô","en":"Your grandpa","de":"Dein Opa","nl":"Je opa","ary":"Jeddek"}},"scenes":{"b1u0":{"set":{"fr":"Au café, ton amie a une grande décision à prendre.","it":"Al bar, la tua amica deve prendere una grande decisione.","es":"En la cafetería, tu amiga tiene que tomar una gran decisión.","pt":"No café, a tua amiga tem uma grande decisão a tomar.","en":"At the café, your friend has a big decision to make.","de":"Im Café muss deine Freundin eine große Entscheidung treffen.","nl":"In het café moet je vriendin een grote beslissing nemen.","ary":"F l-9ahwa, sa7btek 3ndha wa7ed l-9arar kbir."},"lines":[{"r":"amie","fr":"J'hésite à quitter mon travail pour faire le tour du monde. Qu'est-ce que tu en penses ?","it":"Non so se lasciare il lavoro per fare il giro del mondo. Tu che ne pensi?","es":"Dudo si dejar mi trabajo para dar la vuelta al mundo. ¿Tú qué opinas?","pt":"Estou indecisa: deixo o trabalho para dar a volta ao mundo? O que achas?","en":"I'm not sure whether to quit my job and travel round the world. What do you think?","de":"Ich überlege, meinen Job zu kündigen und eine Weltreise zu machen. Was meinst du?","nl":"Ik twijfel of ik mijn baan opzeg om een wereldreis te maken. Wat vind jij?","ary":"Ana mterdda wach nkhelli l-khedma w ndour d-donya. Ach ban lik?"},{"r":"toi","fr":"À mon avis, c'est une bonne idée. Tu en parles depuis des années !","it":"Secondo me è una buona idea. Ne parli da anni!","es":"En mi opinión, es una buena idea. ¡Llevas años hablando de ello!","pt":"Na minha opinião, é uma boa ideia. Falas disso há anos!","en":"In my opinion, it's a good idea. You've been talking about it for years!","de":"Meiner Meinung nach ist das eine gute Idee. Davon redest du schon seit Jahren!","nl":"Volgens mij is het een goed idee. Je hebt het er al jaren over!","ary":"F rayi, fekra mzyana. Hadi snin w nti kathdri 3liha!"},{"r":"amie","fr":"Oui, mais d'un côté j'ai envie de partir, de l'autre j'ai peur de tout perdre.","it":"Sì, ma da un lato ho voglia di partire, dall'altro ho paura di perdere tutto.","es":"Sí, pero por un lado tengo ganas de irme y, por otro, me da miedo perderlo todo.","pt":"Sim, mas por um lado tenho vontade de partir, por outro tenho medo de perder tudo.","en":"Yes, but on the one hand I want to go, and on the other I'm scared of losing everything.","de":"Ja, aber einerseits will ich los, andererseits habe ich Angst, alles zu verlieren.","nl":"Ja, maar aan de ene kant wil ik weg, aan de andere kant ben ik bang alles kwijt te raken.","ary":"Iyeh, walakin men jiha bghit nmchi, w men jiha khra khayfa nkhser koulchi."},{"r":"toi","fr":"Je comprends. Ça dépend : tu as assez d'économies ?","it":"Ti capisco. Dipende: hai abbastanza risparmi?","es":"Te entiendo. Depende: ¿tienes suficientes ahorros?","pt":"Percebo. Depende: tens poupanças suficientes?","en":"I understand. It depends: have you got enough savings?","de":"Verstehe ich. Es kommt darauf an: Hast du genug gespart?","nl":"Ik snap het. Het hangt ervan af: heb je genoeg gespaard?","ary":"Fhemtek. Kayt3alle9: 3ndek l-flous kafyin mjem3in?"},{"r":"amie","fr":"Pour un an, oui. Mais mes parents ne sont pas du tout d'accord.","it":"Per un anno sì. Ma i miei genitori non sono per niente d'accordo.","es":"Para un año, sí. Pero mis padres no están nada de acuerdo.","pt":"Para um ano, sim. Mas os meus pais não concordam nada.","en":"For a year, yes. But my parents don't agree at all.","de":"Für ein Jahr, ja. Aber meine Eltern sind überhaupt nicht einverstanden.","nl":"Voor een jaar wel. Maar mijn ouders zijn het er helemaal niet mee eens.","ary":"L 3am, iyeh. Walakin waldiya ma mtafqinch m3aya b7al walou."},{"r":"toi","fr":"Je pense que c'est ta vie. Si tu ne pars pas maintenant, tu le regretteras.","it":"Penso che sia la tua vita. Se non parti adesso, te ne pentirai.","es":"Creo que es tu vida. Si no te vas ahora, te arrepentirás.","pt":"Acho que a vida é tua. Se não fores agora, vais arrepender-te.","en":"I think it's your life. If you don't go now, you'll regret it.","de":"Ich finde, es ist dein Leben. Wenn du jetzt nicht gehst, wirst du es bereuen.","nl":"Ik vind dat het jouw leven is. Als je nu niet gaat, krijg je er spijt van.","ary":"Ana kanchouf belli hadi 7yatek. Ila ma mchitich daba, ghadi tnedmi."},{"r":"amie","fr":"Tu n'as pas tort… Je vais y réfléchir sérieusement.","it":"Non hai torto… Ci penserò seriamente.","es":"No te falta razón… Lo voy a pensar en serio.","pt":"Não deixas de ter razão… Vou pensar nisso a sério.","en":"You're not wrong… I'll think about it seriously.","de":"Da hast du nicht unrecht… Ich denke ernsthaft darüber nach.","nl":"Je hebt geen ongelijk… Ik ga er serieus over nadenken.","ary":"3ndek l-7e99… Ghadi nfekker fiha mzyan."}]},"b1u1":{"set":{"fr":"Entretien d'embauche pour un poste de vendeur. La recruteuse t'accueille.","it":"Colloquio di lavoro per un posto da commesso. La selezionatrice ti accoglie.","es":"Entrevista de trabajo para un puesto de vendedor. La entrevistadora te recibe.","pt":"Entrevista de emprego para um lugar de vendedor. A recrutadora recebe-te.","en":"A job interview for a sales position. The interviewer welcomes you.","de":"Vorstellungsgespräch für eine Stelle im Verkauf. Die Personalerin begrüßt dich.","nl":"Sollicitatiegesprek voor een baan als verkoper. De recruiter ontvangt je.","ary":"Entretien d l-khedma l blasa d l-bi3. L-mas2oula katsta9blek."},"lines":[{"r":"recruteuse","fr":"Bonjour, asseyez-vous. Parlez-moi un peu de vous.","it":"Buongiorno, si accomodi. Mi parli un po' di lei.","es":"Buenos días, siéntese. Hábleme un poco de usted.","pt":"Bom dia, sente-se. Fale-me um pouco de si.","en":"Hello, have a seat. Tell me a little about yourself.","de":"Guten Tag, setzen Sie sich. Erzählen Sie mir etwas über sich.","nl":"Goedendag, gaat u zitten. Vertelt u eens iets over uzelf.","ary":"Salam, gles. 3awed liya chwiya 3lik."},{"r":"toi","fr":"J'ai cinq ans d'expérience dans la vente, et je parle trois langues.","it":"Ho cinque anni di esperienza nelle vendite e parlo tre lingue.","es":"Tengo cinco años de experiencia en ventas y hablo tres idiomas.","pt":"Tenho cinco anos de experiência em vendas e falo três línguas.","en":"I have five years' experience in sales, and I speak three languages.","de":"Ich habe fünf Jahre Erfahrung im Verkauf und spreche drei Sprachen.","nl":"Ik heb vijf jaar ervaring in de verkoop en ik spreek drie talen.","ary":"3ndi khems snin d t-tajriba f l-bi3, w kanhder tlata d l-loughat."},{"r":"recruteuse","fr":"Très bien. Quels sont vos points forts ?","it":"Molto bene. Quali sono i suoi punti di forza?","es":"Muy bien. ¿Cuáles son sus puntos fuertes?","pt":"Muito bem. Quais são os seus pontos fortes?","en":"Very good. What are your strengths?","de":"Sehr gut. Was sind Ihre Stärken?","nl":"Heel goed. Wat zijn uw sterke punten?","ary":"Mzyan. Chnou homa n-ni9at l-9wiya dyalek?"},{"r":"toi","fr":"Je suis motivé et organisé, et j'aime travailler en équipe.","it":"Sono motivato e organizzato, e mi piace lavorare in squadra.","es":"Soy motivado y organizado, y me gusta trabajar en equipo.","pt":"Sou motivado e organizado, e gosto de trabalhar em equipa.","en":"I'm motivated and organised, and I like working in a team.","de":"Ich bin motiviert und organisiert und arbeite gern im Team.","nl":"Ik ben gemotiveerd en georganiseerd, en ik werk graag in een team.","ary":"Ana motivé w mnaddem, w kanbghi nkhdem m3a l-équipe."},{"r":"recruteuse","fr":"Et pourquoi voulez-vous quitter votre poste actuel ?","it":"E perché vuole lasciare il suo lavoro attuale?","es":"¿Y por qué quiere dejar su puesto actual?","pt":"E porque quer deixar o seu emprego atual?","en":"And why do you want to leave your current job?","de":"Und warum möchten Sie Ihre jetzige Stelle verlassen?","nl":"En waarom wilt u uw huidige baan verlaten?","ary":"W 3lach bghiti tkhelli l-khedma dyalek daba?"},{"r":"toi","fr":"Je cherche de nouvelles responsabilités, et votre entreprise m'intéresse beaucoup.","it":"Cerco nuove responsabilità, e la vostra azienda mi interessa molto.","es":"Busco nuevas responsabilidades, y su empresa me interesa mucho.","pt":"Procuro novas responsabilidades, e a vossa empresa interessa-me muito.","en":"I'm looking for new responsibilities, and your company really interests me.","de":"Ich suche neue Verantwortung, und Ihr Unternehmen interessiert mich sehr.","nl":"Ik zoek nieuwe verantwoordelijkheden, en uw bedrijf spreekt me erg aan.","ary":"Kan9elleb 3la mas2ouliyat jdad, w ch-charika dyalkom kat3jebni bezzaf."},{"r":"recruteuse","fr":"Parfait. Nous vous rappellerons avant la fin de la semaine.","it":"Perfetto. La richiameremo entro la fine della settimana.","es":"Perfecto. Le llamaremos antes del final de la semana.","pt":"Perfeito. Voltamos a ligar-lhe até ao fim da semana.","en":"Perfect. We'll call you back before the end of the week.","de":"Perfekt. Wir melden uns bis Ende der Woche bei Ihnen.","nl":"Prima. We bellen u voor het einde van de week terug.","ary":"Mzyan. Ghadi n3aytou lik 9bel ma tsali s-simana."}]},"b1u2":{"set":{"fr":"À l'aéroport. Le tapis s'est arrêté et ta valise n'est pas là.","it":"All'aeroporto. Il nastro si è fermato e la tua valigia non c'è.","es":"En el aeropuerto. La cinta se ha parado y tu maleta no está.","pt":"No aeroporto. O tapete parou e a tua mala não está lá.","en":"At the airport. The carousel has stopped and your suitcase isn't there.","de":"Am Flughafen. Das Gepäckband steht still, und dein Koffer ist nicht da.","nl":"Op het vliegveld. De bagageband is gestopt en je koffer is er niet.","ary":"F l-matar. T-tapis we9ef w l-valise dyalek ma kaynach."},"lines":[{"r":"toi","fr":"Bonjour, j'ai perdu ma valise. Elle n'est pas arrivée sur le tapis.","it":"Buongiorno, ho perso la valigia. Non è arrivata sul nastro.","es":"Buenos días, he perdido mi maleta. No ha salido por la cinta.","pt":"Bom dia, perdi a minha mala. Não apareceu no tapete.","en":"Hello, I've lost my suitcase. It didn't come out on the carousel.","de":"Guten Tag, ich habe meinen Koffer verloren. Er ist nicht auf dem Band angekommen.","nl":"Goedendag, ik ben mijn koffer kwijt. Hij is niet op de band gekomen.","ary":"Salam, wddert l-valise dyali. Ma jatch f t-tapis."},{"r":"agentvol","fr":"Je suis désolé. Vous avez votre ticket de bagage ?","it":"Mi dispiace. Ha lo scontrino del bagaglio?","es":"Lo siento. ¿Tiene el resguardo del equipaje?","pt":"Lamento. Tem o talão da bagagem?","en":"I'm sorry. Do you have your baggage tag?","de":"Das tut mir leid. Haben Sie Ihren Gepäckschein?","nl":"Het spijt me. Heeft u uw bagagelabel?","ary":"Sme7 lina. 3ndek l-woussl d l-bagage?"},{"r":"toi","fr":"Oui, le voici. J'étais sur le vol de huit heures.","it":"Sì, eccolo. Ero sul volo delle otto.","es":"Sí, aquí lo tiene. Iba en el vuelo de las ocho.","pt":"Sim, aqui está. Vinha no voo das oito.","en":"Yes, here it is. I was on the eight o'clock flight.","de":"Ja, hier. Ich war im Flug um acht Uhr.","nl":"Ja, alstublieft. Ik zat op de vlucht van acht uur.","ary":"Iyeh, ha howa. Kont f t-tiyara d t-tmenya."},{"r":"agentvol","fr":"Votre valise est restée à l'aéroport de départ. Elle arrivera demain matin.","it":"La sua valigia è rimasta all'aeroporto di partenza. Arriverà domani mattina.","es":"Su maleta se ha quedado en el aeropuerto de salida. Llegará mañana por la mañana.","pt":"A sua mala ficou no aeroporto de partida. Chega amanhã de manhã.","en":"Your suitcase stayed at the departure airport. It'll arrive tomorrow morning.","de":"Ihr Koffer ist am Abflughafen geblieben. Er kommt morgen früh an.","nl":"Uw koffer is op het vertrekvliegveld gebleven. Hij komt morgenochtend aan.","ary":"L-valise dyalek b9at f l-matar lli khrejti mennou. Ghadi tousal ghedda f s-sba7."},{"r":"toi","fr":"Demain ? Mais toutes mes affaires sont dedans ! Quelle est la solution ?","it":"Domani? Ma tutte le mie cose sono lì dentro! Qual è la soluzione?","es":"¿Mañana? ¡Pero todas mis cosas están dentro! ¿Cuál es la solución?","pt":"Amanhã? Mas as minhas coisas estão todas lá dentro! Qual é a solução?","en":"Tomorrow? But all my things are in it! What's the solution?","de":"Morgen? Aber alle meine Sachen sind darin! Was ist die Lösung?","nl":"Morgen? Maar al mijn spullen zitten erin! Wat is de oplossing?","ary":"Ghedda? Walakin 7wayji kamlin fiha! Chnou l-7all?"},{"r":"agentvol","fr":"On vous la livre à votre hôtel. Achetez le nécessaire, on vous remboursera.","it":"Gliela consegniamo in albergo. Compri il necessario, la rimborseremo.","es":"Se la llevamos a su hotel. Compre lo necesario y se lo reembolsaremos.","pt":"Entregamos-lha no hotel. Compre o necessário, que nós reembolsamos.","en":"We'll deliver it to your hotel. Buy what you need and we'll refund you.","de":"Wir liefern ihn in Ihr Hotel. Kaufen Sie das Nötigste, wir erstatten es Ihnen.","nl":"We bezorgen hem bij uw hotel. Koop wat u nodig heeft, we vergoeden het.","ary":"Ghadi njibouha lik l l-otel. Chri dakchi lli khassek, w ghadi nrj3ou lik l-flous."}]},"b1u3":{"set":{"fr":"Un dimanche chez ton grand-père. Il te montre une vieille photo.","it":"Una domenica da tuo nonno. Ti mostra una vecchia foto.","es":"Un domingo en casa de tu abuelo. Te enseña una foto antigua.","pt":"Um domingo em casa do teu avô. Ele mostra-te uma fotografia antiga.","en":"A Sunday at your grandpa's. He shows you an old photo.","de":"Ein Sonntag bei deinem Opa. Er zeigt dir ein altes Foto.","nl":"Een zondag bij je opa. Hij laat je een oude foto zien.","ary":"Nhar l-7edd 3nd jeddek. Kayweri lik tswira 9dima."},"lines":[{"r":"grandpere","fr":"Regarde cette photo. C'est moi, à dix ans, devant notre maison.","it":"Guarda questa foto. Sono io, a dieci anni, davanti a casa nostra.","es":"Mira esta foto. Soy yo, a los diez años, delante de nuestra casa.","pt":"Olha esta fotografia. Sou eu, aos dez anos, em frente da nossa casa.","en":"Look at this photo. That's me, aged ten, in front of our house.","de":"Schau dir dieses Foto an. Das bin ich mit zehn, vor unserem Haus.","nl":"Kijk eens naar deze foto. Dat ben ik, tien jaar oud, voor ons huis.","ary":"Chouf had t-tswira. Hada ana, 3ndi 3achra d s-snin, 9eddam darna."},{"r":"toi","fr":"Tu habitais à la campagne ?","it":"Abitavi in campagna?","es":"¿Vivías en el campo?","pt":"Vivias no campo?","en":"Did you live in the countryside?","de":"Hast du auf dem Land gewohnt?","nl":"Woonde je op het platteland?","ary":"Kont saken f l-3roubiya?"},{"r":"grandpere","fr":"Oui. Nous jouions dans la rue toute la journée, il n'y avait presque pas de voitures.","it":"Sì. Giocavamo in strada tutto il giorno, non c'erano quasi macchine.","es":"Sí. Jugábamos en la calle todo el día, casi no había coches.","pt":"Sim. Brincávamos na rua o dia todo, quase não havia carros.","en":"Yes. We played in the street all day; there were hardly any cars.","de":"Ja. Wir haben den ganzen Tag auf der Straße gespielt, es gab kaum Autos.","nl":"Ja. We speelden de hele dag op straat, er waren bijna geen auto's.","ary":"Iyeh. Konna kanl3bou f z-zen9a n-nhar kamel, t9riban ma kanouch t-tomobilat."},{"r":"toi","fr":"Et vous n'aviez pas de téléphones portables !","it":"E non avevate i cellulari!","es":"¡Y no teníais móviles!","pt":"E não tinham telemóveis!","en":"And you didn't have mobile phones!","de":"Und ihr hattet keine Handys!","nl":"En jullie hadden geen mobieltjes!","ary":"W ma kanouch 3ndkom t-tilifounat!"},{"r":"grandpere","fr":"Non ! Le soir, mon grand-père racontait des histoires au coin du feu.","it":"No! La sera mio nonno raccontava storie accanto al fuoco.","es":"¡No! Por la noche, mi abuelo contaba historias junto al fuego.","pt":"Não! À noite, o meu avô contava histórias à lareira.","en":"No! In the evenings my grandpa told stories by the fire.","de":"Nein! Abends hat mein Opa am Feuer Geschichten erzählt.","nl":"Nee! 's Avonds vertelde mijn opa verhalen bij het vuur.","ary":"La! F l-lil, jeddi kan ki7ki l-7kayat 7da l-3afya."},{"r":"toi","fr":"Ça devait être une belle époque.","it":"Doveva essere un bel periodo.","es":"Debía de ser una época bonita.","pt":"Devia ser uma época bonita.","en":"It must have been a lovely time.","de":"Das muss eine schöne Zeit gewesen sein.","nl":"Dat moet een mooie tijd geweest zijn.","ary":"Kan khasso ykoun wa7ed z-zman zwin."},{"r":"grandpere","fr":"Oui… Je me souviens de chaque été passé là-bas.","it":"Sì… Mi ricordo di ogni estate passata lì.","es":"Sí… Me acuerdo de cada verano que pasé allí.","pt":"Sim… Lembro-me de cada verão que lá passei.","en":"Yes… I remember every summer I spent there.","de":"Ja… Ich erinnere mich an jeden Sommer dort.","nl":"Ja… Ik herinner me elke zomer die ik daar doorbracht.","ary":"Iyeh… Kantfekker koll sif douwezto temma."}]},"b1u4":{"set":{"fr":"Ton ami a reçu une offre de travail à l'étranger. Il te demande conseil.","it":"Il tuo amico ha ricevuto un'offerta di lavoro all'estero. Ti chiede un consiglio.","es":"Tu amigo ha recibido una oferta de trabajo en el extranjero. Te pide consejo.","pt":"O teu amigo recebeu uma oferta de emprego no estrangeiro. Pede-te um conselho.","en":"Your friend has been offered a job abroad. He asks for your advice.","de":"Dein Freund hat ein Jobangebot im Ausland bekommen. Er fragt dich um Rat.","nl":"Je vriend heeft een baan in het buitenland aangeboden gekregen. Hij vraagt je om raad.","ary":"Sa7bek jah 3ard d l-khedma f l-kharij. Kaytleb mennek n-nasi7a."},"lines":[{"r":"ami","fr":"On m'a proposé un poste à Montréal. Qu'est-ce que tu ferais, toi ?","it":"Mi hanno offerto un posto a Montréal. Tu che cosa faresti?","es":"Me han ofrecido un puesto en Montreal. ¿Tú qué harías?","pt":"Ofereceram-me um lugar em Montreal. O que farias tu?","en":"I've been offered a job in Montreal. What would you do?","de":"Man hat mir eine Stelle in Montreal angeboten. Was würdest du machen?","nl":"Ik kan een baan krijgen in Montreal. Wat zou jij doen?","ary":"3erdou 3liya khedma f Montréal. Nta ach kont ghadi dir?"},{"r":"toi","fr":"Si j'étais toi, j'accepterais tout de suite !","it":"Se fossi in te, accetterei subito!","es":"Si yo fuera tú, aceptaría enseguida.","pt":"Se fosse a ti, aceitava logo!","en":"If I were you, I'd accept straight away!","de":"Wenn ich du wäre, würde ich sofort annehmen!","nl":"Als ik jou was, zou ik meteen ja zeggen!","ary":"Ila kont f blastek, kont ghadi n9bel daba!"},{"r":"ami","fr":"Mais si je partais, je ne verrais plus ma famille.","it":"Ma se partissi, non vedrei più la mia famiglia.","es":"Pero si me fuera, no vería a mi familia.","pt":"Mas se partisse, deixava de ver a minha família.","en":"But if I left, I wouldn't see my family any more.","de":"Aber wenn ich ginge, würde ich meine Familie nicht mehr sehen.","nl":"Maar als ik wegging, zou ik mijn familie niet meer zien.","ary":"Walakin ila mchit, ma b9itch ghadi nchouf l-3a2ila dyali."},{"r":"toi","fr":"Tu pourrais revenir pour les vacances. Et ce serait une super expérience.","it":"Potresti tornare per le vacanze. E sarebbe un'esperienza bellissima.","es":"Podrías volver en vacaciones. Y sería una experiencia genial.","pt":"Podias voltar nas férias. E seria uma experiência incrível.","en":"You could come back for the holidays. And it would be a great experience.","de":"Du könntest in den Ferien zurückkommen. Und es wäre eine tolle Erfahrung.","nl":"Je zou in de vakanties terug kunnen komen. En het zou een geweldige ervaring zijn.","ary":"T9der trje3 f l-3otla. W ghadi tkoun tajriba zwina bezzaf."},{"r":"ami","fr":"C'est vrai… J'aimerais bien vivre à l'étranger un jour.","it":"È vero… Mi piacerebbe vivere all'estero un giorno.","es":"Es verdad… Me gustaría vivir en el extranjero algún día.","pt":"É verdade… Gostava de viver no estrangeiro um dia.","en":"That's true… I'd like to live abroad one day.","de":"Stimmt… Ich würde gern mal im Ausland leben.","nl":"Dat is waar… Ik zou graag eens in het buitenland wonen.","ary":"Sa7… Kont baghi n3ich f l-kharij chi nhar."},{"r":"toi","fr":"À ta place, je n'hésiterais pas. Et moi, je viendrais te voir !","it":"Al posto tuo non esiterei. E io verrei a trovarti!","es":"Yo que tú, no lo dudaría. ¡Y yo iría a verte!","pt":"No teu lugar, não hesitava. E eu ia visitar-te!","en":"In your shoes, I wouldn't hesitate. And I'd come and visit you!","de":"An deiner Stelle würde ich nicht zögern. Und ich würde dich besuchen!","nl":"In jouw plaats zou ik niet twijfelen. En ik zou je komen opzoeken!","ary":"F blastek, ma kontch ghadi ntrdded. W ana nji nzourek!"}]},"b1u5":{"set":{"fr":"Réunion de quartier : on parle de la propreté du parc.","it":"Riunione di quartiere: si parla della pulizia del parco.","es":"Reunión de vecinos: se habla de la limpieza del parque.","pt":"Reunião de bairro: fala-se da limpeza do parque.","en":"A neighbourhood meeting about keeping the park clean.","de":"Nachbarschaftstreffen: Es geht um die Sauberkeit im Park.","nl":"Buurtvergadering: het gaat over het schoonhouden van het park.","ary":"Ijtima3 d l-7ouma: kayhdrou 3la n-n9a d l-7di9a."},"lines":[{"r":"voisine","fr":"Il y a de plus en plus de déchets dans le parc. Il faut faire quelque chose.","it":"Nel parco ci sono sempre più rifiuti. Bisogna fare qualcosa.","es":"Hay cada vez más basura en el parque. Hay que hacer algo.","pt":"Há cada vez mais lixo no parque. É preciso fazer alguma coisa.","en":"There's more and more rubbish in the park. We need to do something.","de":"Im Park gibt es immer mehr Müll. Wir müssen etwas tun.","nl":"Er ligt steeds meer afval in het park. We moeten iets doen.","ary":"Kayn z-zbel kter w kter f l-7di9a. Khassna ndirou chi 7aja."},{"r":"toi","fr":"Je suis d'accord. On pourrait installer des poubelles pour recycler.","it":"Sono d'accordo. Potremmo mettere dei bidoni per la raccolta differenziata.","es":"Estoy de acuerdo. Podríamos poner contenedores para reciclar.","pt":"Concordo. Podíamos pôr contentores para reciclar.","en":"I agree. We could put in recycling bins.","de":"Einverstanden. Wir könnten Mülltonnen zum Recyceln aufstellen.","nl":"Ik ben het met je eens. We zouden afvalbakken voor recycling kunnen plaatsen.","ary":"Mtafe9. N9dro n7ettou t-tbalat d r-recyclage."},{"r":"voisine","fr":"Bonne idée. Et il faudrait aussi organiser une journée de nettoyage.","it":"Buona idea. E bisognerebbe anche organizzare una giornata di pulizia.","es":"Buena idea. Y también habría que organizar un día de limpieza.","pt":"Boa ideia. E também era preciso organizar um dia de limpeza.","en":"Good idea. And we should also organise a clean-up day.","de":"Gute Idee. Und wir sollten auch einen Aufräumtag organisieren.","nl":"Goed idee. En we zouden ook een opruimdag moeten organiseren.","ary":"Fekra mzyana. W khassna 7tta nnddmou nhar d t-tn9iya."},{"r":"toi","fr":"On pourrait le proposer à l'école : les enfants adorent ça.","it":"Potremmo proporlo alla scuola: ai bambini piace tantissimo.","es":"Podríamos proponérselo al colegio: a los niños les encanta.","pt":"Podíamos propor isso à escola: as crianças adoram.","en":"We could suggest it to the school: the kids love that.","de":"Wir könnten es der Schule vorschlagen: Kinder lieben so etwas.","nl":"We zouden het aan de school kunnen voorstellen: kinderen vinden dat geweldig.","ary":"N9dro n9ter7ouha 3la l-madrasa: d-drari kaymoutou 3la had l-7aja."},{"r":"voisine","fr":"Et puis, il faut moins prendre la voiture. La pollution est terrible ici.","it":"E poi bisogna usare meno la macchina. L'inquinamento qui è terribile.","es":"Y además, hay que usar menos el coche. La contaminación aquí es terrible.","pt":"E depois, é preciso usar menos o carro. A poluição aqui é terrível.","en":"And we need to drive less. The pollution here is terrible.","de":"Und wir müssen weniger Auto fahren. Die Luftverschmutzung hier ist schlimm.","nl":"En we moeten minder de auto pakken. De vervuiling hier is verschrikkelijk.","ary":"W zid, khassna nkhedmou t-tomobil 9el. T-talawwout hna khayb bezzaf."},{"r":"toi","fr":"C'est vrai. Si la mairie améliorait les transports en commun, ce serait plus facile.","it":"È vero. Se il comune migliorasse i mezzi pubblici, sarebbe più facile.","es":"Es verdad. Si el ayuntamiento mejorara el transporte público, sería más fácil.","pt":"É verdade. Se a câmara melhorasse os transportes públicos, seria mais fácil.","en":"True. If the council improved public transport, it would be easier.","de":"Stimmt. Wenn die Stadt den Nahverkehr verbessern würde, wäre es einfacher.","nl":"Klopt. Als de gemeente het openbaar vervoer zou verbeteren, zou het makkelijker zijn.","ary":"Sa7. Ila l-baladiya 7ssnat n-n9l l-3oumoumi, ghadi tkoun sahla."}]},"b1u6":{"set":{"fr":"Ton amie revient de l'aéroport : elle a revu son frère après trois ans.","it":"La tua amica torna dall'aeroporto: ha rivisto suo fratello dopo tre anni.","es":"Tu amiga vuelve del aeropuerto: ha vuelto a ver a su hermano después de tres años.","pt":"A tua amiga volta do aeroporto: reviu o irmão ao fim de três anos.","en":"Your friend is back from the airport: she's seen her brother again after three years.","de":"Deine Freundin kommt vom Flughafen: Sie hat ihren Bruder nach drei Jahren wiedergesehen.","nl":"Je vriendin komt terug van het vliegveld: ze heeft haar broer na drie jaar weer gezien.","ary":"Sa7btek rej3at men l-matar: chafet khaha men b3d tlat snin."},"lines":[{"r":"toi","fr":"Alors, comment ça s'est passé ?","it":"Allora, com'è andata?","es":"¿Y bien? ¿Qué tal fue?","pt":"Então, como correu?","en":"So, how did it go?","de":"Und, wie war's?","nl":"En, hoe ging het?","ary":"Iwa, kifach douwezti?"},{"r":"amie","fr":"J'étais tellement contente de le revoir ! J'ai pleuré dès qu'il est arrivé.","it":"Ero così contenta di rivederlo! Ho pianto appena è arrivato.","es":"¡Estaba tan contenta de volver a verlo! Lloré en cuanto llegó.","pt":"Estava tão contente por voltar a vê-lo! Chorei assim que ele chegou.","en":"I was so happy to see him again! I cried as soon as he arrived.","de":"Ich habe mich so gefreut, ihn wiederzusehen! Ich habe geweint, sobald er da war.","nl":"Ik was zo blij om hem weer te zien! Ik moest huilen zodra hij aankwam.","ary":"Kont fer7ana bezzaf mlli chftou! Bkit gha wsel."},{"r":"toi","fr":"Ça ne m'étonne pas. Trois ans, c'est long.","it":"Non mi stupisce. Tre anni sono tanti.","es":"No me extraña. Tres años es mucho tiempo.","pt":"Não me admira. Três anos é muito tempo.","en":"I'm not surprised. Three years is a long time.","de":"Das wundert mich nicht. Drei Jahre sind lang.","nl":"Dat verbaast me niet. Drie jaar is lang.","ary":"Ma sta3jbtch. Tlat snin bezzaf."},{"r":"amie","fr":"Oui… Je me sentais un peu seule sans lui.","it":"Sì… Mi sentivo un po' sola senza di lui.","es":"Sí… Me sentía un poco sola sin él.","pt":"Sim… Sentia-me um pouco sozinha sem ele.","en":"Yes… I felt a bit lonely without him.","de":"Ja… Ohne ihn habe ich mich ein bisschen einsam gefühlt.","nl":"Ja… Ik voelde me een beetje alleen zonder hem.","ary":"Iyeh… Kont kan7ess b chwiya d l-wa7da bla bih."},{"r":"toi","fr":"Et lui, il allait bien ?","it":"E lui stava bene?","es":"¿Y él estaba bien?","pt":"E ele, estava bem?","en":"And was he OK?","de":"Und ging es ihm gut?","nl":"En ging het goed met hem?","ary":"W howa, kan labas?"},{"r":"amie","fr":"Il avait l'air fatigué, mais heureux. Ça m'a vraiment touchée.","it":"Sembrava stanco, ma felice. Mi ha davvero commosso.","es":"Parecía cansado, pero feliz. Me emocionó mucho.","pt":"Parecia cansado, mas feliz. Fiquei mesmo comovida.","en":"He looked tired, but happy. It really moved me.","de":"Er sah müde aus, aber glücklich. Das hat mich sehr berührt.","nl":"Hij zag er moe uit, maar gelukkig. Dat raakte me echt.","ary":"Kan ban 3iyyan, walakin fer7an. Hadchi atter fiya bezzaf."},{"r":"toi","fr":"Je suis content pour toi. Ça se voit, tu n'arrives pas à cacher ta joie !","it":"Sono contento per te. Si vede, non riesci a nascondere la tua gioia!","es":"Me alegro por ti. ¡Se nota, no puedes esconder tu alegría!","pt":"Fico contente por ti. Nota-se, não consegues esconder a alegria!","en":"I'm happy for you. It shows, you can't hide your joy!","de":"Ich freue mich für dich. Man sieht es, du kannst deine Freude nicht verbergen!","nl":"Ik ben blij voor je. Je ziet het, je kunt je vreugde niet verbergen!","ary":"Fer7an lik. Bayna, ma 9aderach tkhebbi l-fer7a dyalek!"}]},"b1u7":{"set":{"fr":"Hier, ton ami t'a posé un lapin. Aujourd'hui, il vient s'expliquer.","it":"Ieri il tuo amico ti ha dato buca. Oggi viene a spiegarsi.","es":"Ayer tu amigo te dejó plantado. Hoy viene a darte explicaciones.","pt":"Ontem o teu amigo deixou-te pendurado. Hoje vem explicar-se.","en":"Yesterday your friend stood you up. Today he comes to explain.","de":"Gestern hat dich dein Freund versetzt. Heute kommt er, um sich zu erklären.","nl":"Gisteren liet je vriend je zitten. Vandaag komt hij het uitleggen.","ary":"Lbare7 sa7bek khellak tsennah w ma jach. L-youm ja ychre7 lik."},"lines":[{"r":"ami","fr":"Écoute… je suis désolé pour hier. Je ne voulais pas te blesser.","it":"Senti… mi dispiace per ieri. Non volevo ferirti.","es":"Oye… siento lo de ayer. No quería hacerte daño.","pt":"Ouve… desculpa por ontem. Não te queria magoar.","en":"Listen… I'm sorry about yesterday. I didn't mean to hurt you.","de":"Hör mal… Das gestern tut mir leid. Ich wollte dich nicht verletzen.","nl":"Luister… sorry voor gisteren. Ik wilde je niet kwetsen.","ary":"Sme3… sme7 liya 3la lbare7. Ma kontch baghi nje7k."},{"r":"toi","fr":"Tu aurais pu me prévenir que tu ne venais pas. Je t'ai attendu une heure !","it":"Avresti potuto avvisarmi che non venivi. Ti ho aspettato un'ora!","es":"Podrías haberme avisado de que no venías. ¡Te esperé una hora!","pt":"Podias ter-me avisado de que não vinhas. Esperei por ti uma hora!","en":"You could have told me you weren't coming. I waited an hour for you!","de":"Du hättest mir Bescheid sagen können, dass du nicht kommst. Ich habe eine Stunde gewartet!","nl":"Je had me kunnen laten weten dat je niet kwam. Ik heb een uur op je gewacht!","ary":"Kan t9der tgoul liya belli ma jaych. Tsennitek sa3a!"},{"r":"ami","fr":"Tu as raison. Mon téléphone était à plat, mais ce n'est pas une excuse.","it":"Hai ragione. Avevo il telefono scarico, ma non è una scusa.","es":"Tienes razón. Tenía el móvil sin batería, pero eso no es excusa.","pt":"Tens razão. Tinha o telemóvel sem bateria, mas isso não é desculpa.","en":"You're right. My phone was dead, but that's no excuse.","de":"Du hast recht. Mein Handy war leer, aber das ist keine Ausrede.","nl":"Je hebt gelijk. Mijn telefoon was leeg, maar dat is geen excuus.","ary":"3ndek l-7e99. T-tilifoun dyali kan tafi, walakin hadi machi 7ojja."},{"r":"toi","fr":"Bon… On s'est disputés pour une bêtise, en fait.","it":"Va be'… In fondo abbiamo litigato per una sciocchezza.","es":"Bueno… En realidad, nos peleamos por una tontería.","pt":"Pronto… No fundo, discutimos por uma parvoíce.","en":"Well… We actually fell out over something silly.","de":"Na gut… Eigentlich haben wir uns wegen einer Kleinigkeit gestritten.","nl":"Nou ja… Eigenlijk kregen we ruzie om niks.","ary":"Safi… F l-7a9i9a, tkhasmna 3la tfaha."},{"r":"ami","fr":"Oui, c'était un malentendu. On fait la paix ?","it":"Sì, è stato un malinteso. Facciamo pace?","es":"Sí, fue un malentendido. ¿Hacemos las paces?","pt":"Sim, foi um mal-entendido. Fazemos as pazes?","en":"Yes, it was a misunderstanding. Shall we make up?","de":"Ja, es war ein Missverständnis. Vertragen wir uns wieder?","nl":"Ja, het was een misverstand. Maken we het weer goed?","ary":"Iyeh, kan sou2 t-tafahom. Nt9adaw?"},{"r":"toi","fr":"D'accord, je te pardonne. Mais ne recommence pas !","it":"Va bene, ti perdono. Ma non farlo più!","es":"Vale, te perdono. ¡Pero no lo vuelvas a hacer!","pt":"Está bem, perdoo-te. Mas não voltes a fazer isso!","en":"OK, I forgive you. But don't do it again!","de":"Okay, ich verzeihe dir. Aber mach das nicht noch mal!","nl":"Oké, ik vergeef het je. Maar doe het niet nog eens!","ary":"Wakha, sme7t lik. Walakin ma t3awedhach!"}]},"b1u8":{"set":{"fr":"Samedi, c'est l'anniversaire de Léa. Son ami t'appelle avec une idée.","it":"Sabato è il compleanno di Lea. Un suo amico ti chiama con un'idea.","es":"El sábado es el cumpleaños de Lea. Un amigo suyo te llama con una idea.","pt":"No sábado é o aniversário da Lea. Um amigo dela liga-te com uma ideia.","en":"It's Lea's birthday on Saturday. Her friend calls you with an idea.","de":"Am Samstag hat Lea Geburtstag. Ein Freund von ihr ruft dich mit einer Idee an.","nl":"Zaterdag is Lea jarig. Een vriend van haar belt je met een idee.","ary":"Nhar s-sebt 3id l-milad d Lea. Sa7bha 3ayyet lik b wa7ed l-fekra."},"lines":[{"r":"ami","fr":"Samedi, c'est l'anniversaire de Léa. On lui prépare une fête surprise ?","it":"Sabato è il compleanno di Lea. Le organizziamo una festa a sorpresa?","es":"El sábado es el cumple de Lea. ¿Le preparamos una fiesta sorpresa?","pt":"No sábado é o aniversário da Lea. Preparamos-lhe uma festa surpresa?","en":"It's Lea's birthday on Saturday. Shall we throw her a surprise party?","de":"Samstag hat Lea Geburtstag. Machen wir ihr eine Überraschungsparty?","nl":"Zaterdag is Lea jarig. Zullen we een verrassingsfeestje voor haar geven?","ary":"Nhar s-sebt 3id l-milad d Lea. Nwejjdou lha 7efla mfaj2a?"},{"r":"toi","fr":"Super idée ! On la fait chez moi, il y a de la place.","it":"Ottima idea! La facciamo da me, c'è posto.","es":"¡Qué buena idea! La hacemos en mi casa, hay sitio.","pt":"Ótima ideia! Fazemo-la em minha casa, há espaço.","en":"Great idea! Let's have it at my place, there's room.","de":"Super Idee! Wir machen sie bei mir, da ist Platz.","nl":"Goed idee! We doen het bij mij, er is ruimte genoeg.","ary":"Fekra zwina! Ndirouha f dari, kayn l-blassa."},{"r":"ami","fr":"Parfait. J'invite ses amis de la fac. Chacun apporte quelque chose à boire.","it":"Perfetto. Invito i suoi amici dell'università. Ognuno porta qualcosa da bere.","es":"Perfecto. Invito a sus amigos de la uni. Cada uno trae algo de beber.","pt":"Perfeito. Convido os amigos dela da faculdade. Cada um traz alguma coisa para beber.","en":"Perfect. I'll invite her uni friends. Everyone brings something to drink.","de":"Perfekt. Ich lade ihre Freunde von der Uni ein. Jeder bringt etwas zu trinken mit.","nl":"Perfect. Ik nodig haar vrienden van de uni uit. Iedereen neemt iets te drinken mee.","ary":"Mzyan. Ana n3red 3la s7abha d l-fac. Koll wa7ed yjib chi 7aja l ch-chrb."},{"r":"toi","fr":"Et moi, je m'occupe du gâteau. Mais comment on la fait venir sans qu'elle se doute de rien ?","it":"E io mi occupo della torta. Ma come la facciamo venire senza che sospetti niente?","es":"Y yo me encargo de la tarta. Pero ¿cómo hacemos que venga sin que sospeche nada?","pt":"E eu trato do bolo. Mas como é que a fazemos vir sem ela desconfiar de nada?","en":"And I'll take care of the cake. But how do we get her here without her suspecting anything?","de":"Und ich kümmere mich um den Kuchen. Aber wie kriegen wir sie her, ohne dass sie etwas ahnt?","nl":"En ik zorg voor de taart. Maar hoe krijgen we haar hier zonder dat ze iets vermoedt?","ary":"W ana n9adi l-gato. Walakin kifach njibouha bla ma t7ess b walou?"},{"r":"ami","fr":"Dis-lui que tu as besoin d'aide pour un déménagement !","it":"Dille che hai bisogno di aiuto per un trasloco!","es":"¡Dile que necesitas ayuda con una mudanza!","pt":"Diz-lhe que precisas de ajuda com uma mudança!","en":"Tell her you need help moving house!","de":"Sag ihr, du brauchst Hilfe beim Umzug!","nl":"Zeg dat je hulp nodig hebt bij een verhuizing!","ary":"Goul lha belli khassek l-mou3awana f r-r7il!"},{"r":"toi","fr":"Génial. Surtout, pas un mot à personne !","it":"Geniale. Mi raccomando, acqua in bocca!","es":"Genial. Sobre todo, ¡ni una palabra a nadie!","pt":"Genial. Sobretudo, nem uma palavra a ninguém!","en":"Brilliant. And not a word to anyone!","de":"Genial. Aber kein Wort zu niemandem!","nl":"Geniaal. En geen woord tegen iemand!","ary":"Nadi. W 7dar, 7tta kelma l 7tta wa7ed!"}]},"b1u9":{"set":{"fr":"Les dernières minutes du match. Ton équipe et l'autre sont à égalité.","it":"Gli ultimi minuti della partita. La tua squadra e l'altra sono in parità.","es":"Los últimos minutos del partido. Tu equipo y el otro van empatados.","pt":"Os últimos minutos do jogo. A tua equipa e a outra estão empatadas.","en":"The last minutes of the match. Your team and the other side are level.","de":"Die letzten Minuten des Spiels. Deine Mannschaft und die andere stehen unentschieden.","nl":"De laatste minuten van de wedstrijd. Jouw team en het andere staan gelijk.","ary":"L-d9aye9 l-lakhrin d l-match. L-fer9a dyalek w l-khra mt3adlin."},"lines":[{"r":"coach","fr":"Allez, plus que cinq minutes ! Vous allez y arriver !","it":"Forza, mancano solo cinque minuti! Ce la farete!","es":"¡Vamos, solo quedan cinco minutos! ¡Lo vais a conseguir!","pt":"Vamos, só faltam cinco minutos! Vocês conseguem!","en":"Come on, only five minutes left! You can do it!","de":"Los, nur noch fünf Minuten! Ihr schafft das!","nl":"Kom op, nog maar vijf minuten! Jullie kunnen het!","ary":"Yallah, b9aw ghir khems d9aye9! Ghadi tnje7ou!"},{"r":"toi","fr":"Coach, je crois que je me suis blessé au genou…","it":"Mister, credo di essermi fatto male al ginocchio…","es":"Entrenador, creo que me he hecho daño en la rodilla…","pt":"Mister, acho que me magoei no joelho…","en":"Coach, I think I've hurt my knee…","de":"Trainer, ich glaube, ich habe mich am Knie verletzt…","nl":"Trainer, ik denk dat ik mijn knie heb bezeerd…","ary":"Coach, kandenn tjre7t f r-rkba…"},{"r":"coach","fr":"Tu peux encore courir ? Si on gagne ce match, on sera champions !","it":"Riesci ancora a correre? Se vinciamo questa partita, saremo campioni!","es":"¿Todavía puedes correr? ¡Si ganamos este partido, seremos campeones!","pt":"Ainda consegues correr? Se ganharmos este jogo, somos campeões!","en":"Can you still run? If we win this match, we'll be champions!","de":"Kannst du noch laufen? Wenn wir dieses Spiel gewinnen, sind wir Meister!","nl":"Kun je nog rennen? Als we deze wedstrijd winnen, zijn we kampioen!","ary":"Mazal t9der tjri? Ila rb7na had l-match, ghadi nkounou l-abtal!"},{"r":"toi","fr":"Ça va, je continue. Je ne veux pas lâcher maintenant.","it":"Va bene, continuo. Non voglio mollare adesso.","es":"Estoy bien, sigo. No quiero rendirme ahora.","pt":"Está bem, continuo. Não quero desistir agora.","en":"I'm OK, I'll keep going. I don't want to give up now.","de":"Geht schon, ich mache weiter. Ich will jetzt nicht aufgeben.","nl":"Het gaat, ik ga door. Ik wil nu niet opgeven.","ary":"Labas, ghadi nkemmel. Ma bghitch nstsallem daba."},{"r":"coach","fr":"C'est fini… On a perdu de justesse, mais vous avez bien joué. Je suis fier de vous.","it":"È finita… Abbiamo perso di poco, ma avete giocato bene. Sono fiero di voi.","es":"Se acabó… Hemos perdido por poco, pero habéis jugado bien. Estoy orgulloso de vosotros.","pt":"Acabou… Perdemos por pouco, mas jogaram bem. Tenho orgulho em vocês.","en":"It's over… We lost by a whisker, but you played well. I'm proud of you.","de":"Aus… Wir haben knapp verloren, aber ihr habt gut gespielt. Ich bin stolz auf euch.","nl":"Afgelopen… We hebben nipt verloren, maar jullie hebben goed gespeeld. Ik ben trots op jullie.","ary":"Salat… Khserna b chwiya, walakin l3btou mzyan. Ana fkhour bikom."},{"r":"toi","fr":"L'année prochaine, on gagnera. Je m'entraînerai trois fois par semaine !","it":"L'anno prossimo vinceremo. Mi allenerò tre volte a settimana!","es":"El año que viene ganaremos. ¡Entrenaré tres veces por semana!","pt":"Para o ano ganhamos. Vou treinar três vezes por semana!","en":"Next year we'll win. I'll train three times a week!","de":"Nächstes Jahr gewinnen wir. Ich trainiere dreimal pro Woche!","nl":"Volgend jaar winnen we. Ik ga drie keer per week trainen!","ary":"L-3am j-jay ghadi nrb7ou. Ghadi ntdrreb tlat merrat f s-simana!"}]},"b1u10":{"set":{"fr":"Ta meilleure amie t'appelle. Elle a une nouvelle à t'annoncer.","it":"La tua migliore amica ti chiama. Ha una novità da darti.","es":"Tu mejor amiga te llama. Tiene una noticia que darte.","pt":"A tua melhor amiga liga-te. Tem uma novidade para te contar.","en":"Your best friend calls you. She has some news.","de":"Deine beste Freundin ruft dich an. Sie hat Neuigkeiten.","nl":"Je beste vriendin belt je. Ze heeft nieuws.","ary":"Sa7btek l-9riba 3ayytat lik. 3ndha khbar."},"lines":[{"r":"amie","fr":"Il faut que je te raconte un truc… J'ai rencontré quelqu'un.","it":"Ti devo raccontare una cosa… Ho conosciuto qualcuno.","es":"Tengo que contarte una cosa… He conocido a alguien.","pt":"Tenho de te contar uma coisa… Conheci uma pessoa.","en":"I have to tell you something… I've met someone.","de":"Ich muss dir was erzählen… Ich habe jemanden kennengelernt.","nl":"Ik moet je iets vertellen… Ik heb iemand ontmoet.","ary":"Khassni n3awed lik chi 7aja… T3arft 3la chi wa7ed."},{"r":"toi","fr":"Non ! Raconte ! Vous vous êtes rencontrés où ?","it":"No! Racconta! Dove vi siete conosciuti?","es":"¡No! ¡Cuéntame! ¿Dónde os conocisteis?","pt":"Não! Conta! Onde é que se conheceram?","en":"No way! Tell me! Where did you meet?","de":"Echt? Erzähl! Wo habt ihr euch kennengelernt?","nl":"Echt? Vertel! Waar hebben jullie elkaar ontmoet?","ary":"Bessa7? 3awdi! Fin t3areftou?"},{"r":"amie","fr":"À la fac. Il m'a proposé de prendre un verre après le cours.","it":"All'università. Mi ha proposto di bere qualcosa dopo la lezione.","es":"En la uni. Me propuso tomar algo después de clase.","pt":"Na faculdade. Convidou-me para tomar um copo depois da aula.","en":"At uni. He asked me out for a drink after class.","de":"An der Uni. Er hat mich nach der Vorlesung auf einen Drink eingeladen.","nl":"Op de uni. Hij vroeg of ik na de les iets wilde drinken.","ary":"F l-fac. 3red 3liya nchrbou chi 7aja men b3d d-dars."},{"r":"toi","fr":"Et alors ? Vous sortez ensemble ?","it":"E allora? State insieme?","es":"¿Y qué? ¿Estáis saliendo?","pt":"E então? Estão juntos?","en":"And? Are you going out?","de":"Und? Seid ihr zusammen?","nl":"En? Hebben jullie iets?","ary":"W men b3d? Wach m3a ba3diyatkom?"},{"r":"amie","fr":"Pas encore… Je ne sais pas s'il me plaît vraiment. Tu en penses quoi ?","it":"Non ancora… Non so se mi piace davvero. Tu che ne pensi?","es":"Todavía no… No sé si me gusta de verdad. ¿Tú qué piensas?","pt":"Ainda não… Não sei se gosto mesmo dele. O que achas?","en":"Not yet… I don't know if I really like him. What do you think?","de":"Noch nicht… Ich weiß nicht, ob er mir wirklich gefällt. Was meinst du?","nl":"Nog niet… Ik weet niet of ik hem echt leuk vind. Wat denk jij?","ary":"Mazal… Ma 3reftch wach 3jebni bessa7. Ach ban lik?"},{"r":"toi","fr":"Prends ton temps. Et tu sais, tu peux compter sur moi, je suis là.","it":"Prenditi il tuo tempo. E lo sai, puoi contare su di me, io ci sono.","es":"Tómate tu tiempo. Y ya sabes, puedes contar conmigo, aquí estoy.","pt":"Dá tempo ao tempo. E sabes que podes contar comigo, estou aqui.","en":"Take your time. And you know you can count on me, I'm here.","de":"Lass dir Zeit. Und du weißt, du kannst auf mich zählen, ich bin da.","nl":"Neem je tijd. En je weet het: je kunt op me rekenen, ik ben er.","ary":"Khdi weqtek. W nti 3arfa, t9dri t3awli 3liya, ana hna."}]},"b1u11":{"set":{"fr":"Samedi midi, dans l'appartement. Ni toi ni ta colocataire n'avez envie de rien faire.","it":"Sabato a mezzogiorno, in casa. Né tu né la tua coinquilina avete voglia di fare niente.","es":"Sábado a mediodía, en el piso. Ni tú ni tu compañera de piso tenéis ganas de hacer nada.","pt":"Sábado ao meio-dia, em casa. Nem tu nem a tua colega de casa têm vontade de fazer nada.","en":"Saturday lunchtime in the flat. Neither you nor your flatmate feel like doing anything.","de":"Samstagmittag in der Wohnung. Weder du noch deine Mitbewohnerin habt Lust auf irgendwas.","nl":"Zaterdagmiddag in het appartement. Jij en je huisgenote hebben nergens zin in.","ary":"Nhar s-sebt f t-tna3ch, f ch-che99a. 7tta wa7ed fikom ma 3ndo l-khatar ydir chi 7aja."},"lines":[{"r":"coloc","fr":"J'ai la flemme de faire la vaisselle…","it":"Non ho voglia di lavare i piatti…","es":"Me da una pereza fregar los platos…","pt":"Que preguiça de lavar a loiça…","en":"I can't be bothered to do the washing-up…","de":"Ich hab null Bock auf Abwasch…","nl":"Ik heb geen zin om af te wassen…","ary":"Ma fiyach nghssel l-mwa3en…"},{"r":"toi","fr":"Moi non plus. On la fait ce soir ?","it":"Neanche io. Li laviamo stasera?","es":"Yo tampoco. ¿Los fregamos esta noche?","pt":"Nem eu. Lavamos logo à noite?","en":"Me neither. Shall we do it tonight?","de":"Ich auch nicht. Machen wir ihn heute Abend?","nl":"Ik ook niet. Doen we het vanavond?","ary":"7tta ana. Nghssloum f l-lil?"},{"r":"coloc","fr":"OK. Au fait, on se fait une bouffe avec les autres samedi prochain ?","it":"Ok. A proposito, ci facciamo una mangiata con gli altri sabato prossimo?","es":"Vale. Por cierto, ¿quedamos a comer con los demás el sábado que viene?","pt":"Ok. Já agora, fazemos uma jantarada com os outros no próximo sábado?","en":"OK. By the way, shall we get some food with the others next Saturday?","de":"Okay. Übrigens, wollen wir nächsten Samstag mit den anderen was essen?","nl":"Oké. Trouwens, gaan we volgende zaterdag met de anderen wat eten?","ary":"Wakha. W 3la fekra, nakhlou chi 7aja m3a l-khrin s-sebt j-jay?"},{"r":"toi","fr":"Carrément ! Mais Marc vient ? Il se prend toujours la tête avec tout le monde.","it":"Certo! Ma viene Marco? Litiga sempre con tutti.","es":"¡Claro que sí! Pero ¿viene Marcos? Siempre se pelea con todo el mundo.","pt":"Claro! Mas o Marco vem? Está sempre a chatear-se com toda a gente.","en":"Definitely! But is Mark coming? He always picks fights with everyone.","de":"Auf jeden Fall! Aber kommt Mark? Er legt sich immer mit allen an.","nl":"Zeker weten! Maar komt Mark ook? Hij krijgt altijd met iedereen ruzie.","ary":"Akid! Walakin Marc jay? Dima kaytkhasem m3a ga3 n-nas."},{"r":"coloc","fr":"Qu'il vienne ou pas, je m'en fiche complètement.","it":"Che venga o no, non me ne importa niente.","es":"Que venga o no, me da completamente igual.","pt":"Que venha ou não, estou-me nas tintas.","en":"Whether he comes or not, I couldn't care less.","de":"Ob er kommt oder nicht, ist mir total egal.","nl":"Of hij komt of niet, het kan me echt niks schelen.","ary":"Ja wla ma jach, ma kayhemmnich b7al walou."},{"r":"toi","fr":"Bon… Dépêche-toi, on est grave à la bourre pour le ciné !","it":"Dai… Sbrigati, siamo in super ritardo per il cinema!","es":"Bueno… ¡Date prisa, que llegamos tardísimo al cine!","pt":"Pronto… Despacha-te, estamos mesmo atrasados para o cinema!","en":"Right… Hurry up, we're seriously late for the cinema!","de":"Na gut… Beeil dich, wir sind voll spät dran fürs Kino!","nl":"Nou… Schiet op, we zijn echt te laat voor de film!","ary":"Safi… Zrbi, rah m3ettlin bezzaf 3la s-cinema!"}]},"b1u12":{"set":{"fr":"Ton téléphone sonne. C'est une entreprise où tu as postulé.","it":"Squilla il telefono. È un'azienda a cui ti sei candidato.","es":"Suena tu móvil. Es una empresa en la que has echado el currículum.","pt":"O telemóvel toca. É uma empresa a que te candidataste.","en":"Your phone rings. It's a company you applied to.","de":"Dein Handy klingelt. Es ist eine Firma, bei der du dich beworben hast.","nl":"Je telefoon gaat. Het is een bedrijf waar je hebt gesolliciteerd.","ary":"T-tilifoun kayrenn. Hadi wa7ed ch-charika lli 7ettiti 3ndha talab."},"lines":[{"r":"recruteuse","fr":"Bonjour, ici la société Lumen. Vous avez répondu à notre offre d'emploi ?","it":"Buongiorno, sono della ditta Lumen. Ha risposto al nostro annuncio di lavoro?","es":"Buenos días, le llamo de la empresa Lumen. ¿Ha respondido a nuestra oferta de empleo?","pt":"Bom dia, fala da empresa Lumen. Respondeu ao nosso anúncio de emprego?","en":"Hello, this is Lumen. Did you apply for our job offer?","de":"Guten Tag, hier ist die Firma Lumen. Sie haben sich auf unsere Stelle beworben?","nl":"Goedendag, u spreekt met Lumen. Heeft u gereageerd op onze vacature?","ary":"Salam, m3ak ch-charika Lumen. Wach jawebti 3la l-3ard d l-khedma dyalna?"},{"r":"toi","fr":"Oui, tout à fait. J'ai envoyé ma candidature la semaine dernière.","it":"Sì, esatto. Ho mandato la mia candidatura la settimana scorsa.","es":"Sí, exacto. Envié mi candidatura la semana pasada.","pt":"Sim, exatamente. Enviei a minha candidatura na semana passada.","en":"Yes, that's right. I sent my application last week.","de":"Ja, genau. Ich habe meine Bewerbung letzte Woche geschickt.","nl":"Ja, klopt. Ik heb vorige week mijn sollicitatie gestuurd.","ary":"Iyeh, bedebt. Sifet t-talab dyali s-simana lli fatet."},{"r":"recruteuse","fr":"Votre CV nous intéresse. Nous aimerions vous rencontrer pour un entretien.","it":"Il suo curriculum ci interessa. Vorremmo incontrarla per un colloquio.","es":"Su currículum nos interesa. Nos gustaría conocerle en una entrevista.","pt":"O seu CV interessa-nos. Gostaríamos de o conhecer numa entrevista.","en":"We're interested in your CV. We'd like to meet you for an interview.","de":"Ihr Lebenslauf interessiert uns. Wir würden Sie gern zu einem Gespräch einladen.","nl":"Uw cv spreekt ons aan. We willen u graag uitnodigen voor een gesprek.","ary":"S-CV dyalek 3jebna. Bghina ntla9aw m3ak f entretien."},{"r":"toi","fr":"Avec plaisir ! Je n'ai pas encore beaucoup d'expérience, mais j'apprends vite.","it":"Con piacere! Non ho ancora molta esperienza, ma imparo in fretta.","es":"¡Con mucho gusto! Aún no tengo mucha experiencia, pero aprendo rápido.","pt":"Com todo o gosto! Ainda não tenho muita experiência, mas aprendo depressa.","en":"I'd be glad to! I don't have much experience yet, but I learn fast.","de":"Sehr gern! Ich habe noch nicht viel Erfahrung, aber ich lerne schnell.","nl":"Graag! Ik heb nog niet veel ervaring, maar ik leer snel.","ary":"Bkoul farah! Mazal ma 3ndich tajriba bezzaf, walakin kant3allem bezzerba."},{"r":"recruteuse","fr":"C'est ce qu'on cherche : quelqu'un de motivé et autonome. Jeudi à dix heures, ça vous va ?","it":"È quello che cerchiamo: una persona motivata e autonoma. Giovedì alle dieci le va bene?","es":"Es lo que buscamos: alguien motivado y autónomo. ¿Le va bien el jueves a las diez?","pt":"É o que procuramos: alguém motivado e autónomo. Quinta-feira às dez dá-lhe jeito?","en":"That's what we're looking for: someone motivated and independent. Does Thursday at ten suit you?","de":"Genau so jemanden suchen wir: motiviert und selbstständig. Passt Ihnen Donnerstag um zehn?","nl":"Dat zoeken we: iemand die gemotiveerd en zelfstandig is. Komt donderdag om tien uur u uit?","ary":"Hadchi lli kan9elbou 3lih: chi wa7ed motivé w kaykhdem b rasso. Nhar l-khmis m3a l-3achra, mzyan lik?"},{"r":"toi","fr":"Parfait, je serai là. Merci beaucoup !","it":"Perfetto, ci sarò. Grazie mille!","es":"Perfecto, allí estaré. ¡Muchas gracias!","pt":"Perfeito, lá estarei. Muito obrigado!","en":"Perfect, I'll be there. Thank you very much!","de":"Perfekt, ich werde da sein. Vielen Dank!","nl":"Prima, ik zal er zijn. Hartelijk bedankt!","ary":"Mzyan, ghadi nkoun temma. Chokran bezzaf!"}]},"b1u13":{"set":{"fr":"Ton père t'appelle au secours : son ordinateur ne marche plus.","it":"Tuo padre ti chiama in aiuto: il suo computer non funziona più.","es":"Tu padre te pide ayuda: su ordenador ya no funciona.","pt":"O teu pai pede-te ajuda: o computador dele deixou de funcionar.","en":"Your dad calls for help: his computer has stopped working.","de":"Dein Vater ruft um Hilfe: Sein Computer geht nicht mehr.","nl":"Je vader roept je te hulp: zijn computer doet het niet meer.","ary":"Bbak 3ayyet lik y3tek l-mou3awana: l-ordinateur dyalo ma b9ach khddam."},"lines":[{"r":"pere","fr":"Mon ordinateur a planté et je ne peux plus rien faire !","it":"Il computer si è bloccato e non riesco più a fare niente!","es":"¡Se me ha colgado el ordenador y no puedo hacer nada!","pt":"O computador foi abaixo e não consigo fazer nada!","en":"My computer's crashed and I can't do anything!","de":"Mein Computer ist abgestürzt und ich kann nichts mehr machen!","nl":"Mijn computer is vastgelopen en ik kan niks meer!","ary":"L-ordinateur dyali t7bes w ma b9it n9der ndir walou!"},{"r":"toi","fr":"Tu as essayé de l'éteindre et de le rallumer ?","it":"Hai provato a spegnerlo e riaccenderlo?","es":"¿Has probado a apagarlo y volver a encenderlo?","pt":"Já experimentaste desligá-lo e voltar a ligá-lo?","en":"Have you tried turning it off and on again?","de":"Hast du versucht, ihn aus- und wieder einzuschalten?","nl":"Heb je geprobeerd hem uit en weer aan te zetten?","ary":"Jarrebti tteffih w t3awed tch3lou?"},{"r":"pere","fr":"Oui… et maintenant il me demande un mot de passe.","it":"Sì… e adesso mi chiede una password.","es":"Sí… y ahora me pide una contraseña.","pt":"Sim… e agora pede-me uma palavra-passe.","en":"Yes… and now it's asking me for a password.","de":"Ja… und jetzt will er ein Passwort.","nl":"Ja… en nu vraagt hij om een wachtwoord.","ary":"Iyeh… w daba kaytleb menni mot de passe."},{"r":"toi","fr":"C'est celui que tu as noté dans ton carnet, non ?","it":"È quella che hai scritto sul quaderno, no?","es":"Es la que apuntaste en tu libreta, ¿no?","pt":"É a que escreveste no teu caderno, não é?","en":"It's the one you wrote in your notebook, isn't it?","de":"Das ist doch das, was du in dein Notizbuch geschrieben hast, oder?","nl":"Dat is toch het wachtwoord dat je in je boekje hebt geschreven?","ary":"Hadak lli ktebti f l-karni dyalek, yak?"},{"r":"pere","fr":"Je l'ai oublié… pour la troisième fois cette semaine.","it":"L'ho dimenticata… per la terza volta questa settimana.","es":"La he olvidado… por tercera vez esta semana.","pt":"Esqueci-me dela… pela terceira vez esta semana.","en":"I've forgotten it… for the third time this week.","de":"Ich habe es vergessen… zum dritten Mal diese Woche.","nl":"Ik ben het vergeten… voor de derde keer deze week.","ary":"Nsito… l-merra t-talta had s-simana."},{"r":"toi","fr":"Pas de panique, on va le réinitialiser ensemble.","it":"Niente panico, la reimpostiamo insieme.","es":"Tranquilo, la restablecemos juntos.","pt":"Calma, vamos redefini-la juntos.","en":"Don't panic, we'll reset it together.","de":"Keine Panik, wir setzen es zusammen zurück.","nl":"Geen paniek, we stellen het samen opnieuw in.","ary":"Ma tkhafch, ghadi nbeddlouh b jouj."}]},"b1u14":{"set":{"fr":"Au comptoir d'enregistrement de l'aéroport.","it":"Al banco del check-in dell'aeroporto.","es":"En el mostrador de facturación del aeropuerto.","pt":"No balcão de check-in do aeroporto.","en":"At the airport check-in desk.","de":"Am Check-in-Schalter des Flughafens.","nl":"Bij de incheckbalie op het vliegveld.","ary":"F l-guichet d t-tasjil f l-matar."},"lines":[{"r":"agentvol","fr":"Bonjour. Votre passeport, s'il vous plaît. Vous avez un bagage en soute ?","it":"Buongiorno. Il passaporto, per favore. Ha un bagaglio da stiva?","es":"Buenos días. Su pasaporte, por favor. ¿Factura alguna maleta?","pt":"Bom dia. O passaporte, por favor. Tem bagagem de porão?","en":"Hello. Your passport, please. Do you have any hold luggage?","de":"Guten Tag. Ihren Pass, bitte. Haben Sie Gepäck zum Aufgeben?","nl":"Goedendag. Uw paspoort, alstublieft. Heeft u ruimbagage?","ary":"Salam. L-passeport dyalek, 3afak. 3ndek chi bagage l s-soute?"},{"r":"toi","fr":"Oui, cette valise. Je voudrais une place côté hublot, s'il vous plaît.","it":"Sì, questa valigia. Vorrei un posto vicino al finestrino, per favore.","es":"Sí, esta maleta. Quería un asiento de ventanilla, por favor.","pt":"Sim, esta mala. Queria um lugar à janela, por favor.","en":"Yes, this suitcase. I'd like a window seat, please.","de":"Ja, diesen Koffer. Ich hätte gern einen Fensterplatz, bitte.","nl":"Ja, deze koffer. Ik wil graag een plaats bij het raam.","ary":"Iyeh, had l-valise. Bghit blassa 7da s-sherjem, 3afak."},{"r":"agentvol","fr":"C'est noté. Mais votre valise fait deux kilos de trop.","it":"Fatto. Ma la sua valigia pesa due chili di troppo.","es":"Anotado. Pero su maleta pesa dos kilos de más.","pt":"Está registado. Mas a sua mala tem dois quilos a mais.","en":"Done. But your suitcase is two kilos over.","de":"Notiert. Aber Ihr Koffer hat zwei Kilo zu viel.","nl":"Genoteerd. Maar uw koffer is twee kilo te zwaar.","ary":"Wakha. Walakin l-valise dyalek zayda b jouj kilo."},{"r":"toi","fr":"Ah… Je peux mettre quelques affaires dans mon sac à dos ?","it":"Ah… Posso mettere qualcosa nello zaino?","es":"Ah… ¿Puedo meter algunas cosas en la mochila?","pt":"Ah… Posso pôr algumas coisas na mochila?","en":"Oh… Can I put a few things in my backpack?","de":"Ach… Kann ich ein paar Sachen in meinen Rucksack packen?","nl":"O… Mag ik wat spullen in mijn rugzak doen?","ary":"Ah… N9der n7ett chi 7wayej f l-sac à dos dyali?"},{"r":"agentvol","fr":"Bien sûr. Voici votre carte d'embarquement. L'embarquement se fait porte 32 dans quarante minutes.","it":"Certo. Ecco la carta d'imbarco. L'imbarco è al gate 32 tra quaranta minuti.","es":"Claro. Aquí tiene su tarjeta de embarque. El embarque es por la puerta 32 dentro de cuarenta minutos.","pt":"Claro. Aqui está o cartão de embarque. O embarque é na porta 32 daqui a quarenta minutos.","en":"Of course. Here's your boarding pass. Boarding is at gate 32 in forty minutes.","de":"Natürlich. Hier ist Ihre Bordkarte. Das Boarding ist in vierzig Minuten an Gate 32.","nl":"Natuurlijk. Hier is uw instapkaart. Het instappen is over veertig minuten bij gate 32.","ary":"Akid. Hak l-carte d r-rkoub. R-rkoub f l-bab 32 men daba rb3in d9i9a."},{"r":"toi","fr":"Merci. J'ai une correspondance à Lisbonne : j'espère qu'on ne sera pas en retard !","it":"Grazie. Ho una coincidenza a Lisbona: spero che non saremo in ritardo!","es":"Gracias. Tengo una escala en Lisboa: ¡espero que no vayamos con retraso!","pt":"Obrigado. Tenho uma ligação em Lisboa: espero que não haja atraso!","en":"Thanks. I have a connection in Lisbon: I hope we won't be late!","de":"Danke. Ich habe einen Anschlussflug in Lissabon: Hoffentlich haben wir keine Verspätung!","nl":"Dank u. Ik heb een overstap in Lissabon: ik hoop dat we geen vertraging hebben!","ary":"Chokran. 3ndi correspondance f Lisbonne: nchallah ma nt3ettlouch!"}]},"b1u15":{"set":{"fr":"Dimanche soir, sur le canapé avec ta sœur.","it":"Domenica sera, sul divano con tua sorella.","es":"Domingo por la noche, en el sofá con tu hermana.","pt":"Domingo à noite, no sofá com a tua irmã.","en":"Sunday evening on the sofa with your sister.","de":"Sonntagabend auf dem Sofa mit deiner Schwester.","nl":"Zondagavond op de bank met je zus.","ary":"Nhar l-7edd f l-lil, f l-fotay m3a khtek."},"lines":[{"r":"soeur","fr":"Tu devrais regarder cette série, elle est géniale. J'ai vu toute la saison en un week-end !","it":"Dovresti guardare questa serie, è fantastica. Ho visto tutta la stagione in un fine settimana!","es":"Deberías ver esta serie, es genial. ¡Me vi toda la temporada en un fin de semana!","pt":"Devias ver esta série, é incrível. Vi a temporada toda num fim de semana!","en":"You should watch this series, it's brilliant. I watched the whole season in one weekend!","de":"Du solltest diese Serie schauen, die ist genial. Ich habe die ganze Staffel an einem Wochenende gesehen!","nl":"Je moet deze serie kijken, hij is geweldig. Ik heb het hele seizoen in één weekend gekeken!","ary":"Khassek tchouf had s-série, nadia. Chft s-saison kamla f weekend wa7ed!"},{"r":"toi","fr":"C'est quoi ? Un film d'horreur ? Moi, je préfère les comédies.","it":"Che cos'è? Un horror? Io preferisco le commedie.","es":"¿De qué va? ¿De terror? Yo prefiero las comedias.","pt":"O que é? Terror? Eu prefiro comédias.","en":"What is it? Horror? I prefer comedies.","de":"Was ist das? Horror? Ich mag lieber Komödien.","nl":"Wat is het? Horror? Ik heb liever comedy's.","ary":"Chnou hiya? Dyal r-ro3b? Ana kanfeddel l-comédie."},{"r":"soeur","fr":"Non, c'est un thriller. Au début, il y a un meurtre, et en fait le coupable, c'est…","it":"No, è un thriller. All'inizio c'è un omicidio, e in realtà il colpevole è…","es":"No, es un thriller. Al principio hay un asesinato y, en realidad, el culpable es…","pt":"Não, é um thriller. No início há um homicídio e, afinal, o culpado é…","en":"No, it's a thriller. At the start there's a murder, and the killer is actually…","de":"Nein, ein Thriller. Am Anfang gibt es einen Mord, und der Täter ist eigentlich…","nl":"Nee, het is een thriller. In het begin is er een moord, en de dader is eigenlijk…","ary":"La, thriller. F l-bdya kayna jarima, w f l-7a9i9a l-moujrim howa…"},{"r":"toi","fr":"Stop ! Ne me spoile pas !","it":"Basta! Non fare spoiler!","es":"¡Para! ¡No me hagas spoiler!","pt":"Para! Não me faças spoiler!","en":"Stop! No spoilers!","de":"Stopp! Nicht spoilern!","nl":"Stop! Niet spoilen!","ary":"Bezzaf! Ma t-spoilinich!"},{"r":"soeur","fr":"D'accord, d'accord. On regarde le premier épisode ensemble, en VO ?","it":"Va bene, va bene. Guardiamo il primo episodio insieme, in lingua originale?","es":"Vale, vale. ¿Vemos el primer episodio juntos, en versión original?","pt":"Está bem, está bem. Vemos o primeiro episódio juntos, na versão original?","en":"OK, OK. Shall we watch the first episode together, in the original language?","de":"Schon gut. Schauen wir die erste Folge zusammen, im Original?","nl":"Oké, oké. Kijken we samen de eerste aflevering, in de originele taal?","ary":"Wakha, wakha. Nchoufou l-7al9a l-lowla m3a ba3diyatna, b l-lougha l-asliya?"},{"r":"toi","fr":"Oui, avec les sous-titres. Mais si la fin est nulle, c'est toi qui fais la vaisselle !","it":"Sì, con i sottotitoli. Ma se il finale fa schifo, i piatti li lavi tu!","es":"Sí, con subtítulos. Pero si el final es malísimo, ¡friegas tú!","pt":"Sim, com legendas. Mas se o final for mau, és tu que lavas a loiça!","en":"Yes, with subtitles. But if the ending's rubbish, you're doing the washing-up!","de":"Ja, mit Untertiteln. Aber wenn das Ende schlecht ist, spülst du ab!","nl":"Ja, met ondertiteling. Maar als het einde slecht is, doe jij de afwas!","ary":"Iyeh, m3a t-tarjama. Walakin ila kanet n-nihaya khayba, nti lli ghadi tghsli l-mwa3en!"}]},"b1u16":{"set":{"fr":"À la banque. Ce matin, le distributeur a gardé ta carte.","it":"In banca. Stamattina il bancomat si è tenuto la tua carta.","es":"En el banco. Esta mañana el cajero se ha quedado con tu tarjeta.","pt":"No banco. Esta manhã a caixa multibanco ficou com o teu cartão.","en":"At the bank. This morning the cash machine kept your card.","de":"In der Bank. Heute Morgen hat der Geldautomat deine Karte eingezogen.","nl":"Bij de bank. Vanochtend heeft de geldautomaat je pas ingeslikt.","ary":"F l-banka. Had s-sba7 la machine khebbat l-carte dyalek."},"lines":[{"r":"toi","fr":"Bonjour. Ma carte a été avalée par le distributeur ce matin.","it":"Buongiorno. Stamattina il bancomat mi ha trattenuto la carta.","es":"Buenos días. Esta mañana el cajero se ha tragado mi tarjeta.","pt":"Bom dia. Esta manhã a máquina engoliu o meu cartão.","en":"Hello. The cash machine swallowed my card this morning.","de":"Guten Tag. Der Automat hat heute Morgen meine Karte eingezogen.","nl":"Goedendag. De automaat heeft vanochtend mijn pas ingeslikt.","ary":"Salam. La machine bel3at l-carte dyali had s-sba7."},{"r":"conseillere","fr":"Ça arrive. Vous avez tapé un mauvais code PIN ?","it":"Succede. Ha digitato un PIN sbagliato?","es":"Suele pasar. ¿Ha marcado un PIN incorrecto?","pt":"Acontece. Marcou o PIN errado?","en":"It happens. Did you enter the wrong PIN?","de":"Das kommt vor. Haben Sie eine falsche PIN eingegeben?","nl":"Dat gebeurt. Heeft u een verkeerde pincode ingetoetst?","ary":"Kat w9e3. Dkhelti l-code ghalet?"},{"r":"toi","fr":"Oui, trois fois… Et il y a une opération que je ne reconnais pas sur mon compte.","it":"Sì, tre volte… E sul conto c'è un'operazione che non riconosco.","es":"Sí, tres veces… Y hay un movimiento en mi cuenta que no reconozco.","pt":"Sim, três vezes… E há um movimento na minha conta que não reconheço.","en":"Yes, three times… And there's a transaction on my account I don't recognise.","de":"Ja, dreimal… Und auf meinem Konto ist eine Buchung, die ich nicht kenne.","nl":"Ja, drie keer… En er staat een transactie op mijn rekening die ik niet herken.","ary":"Iyeh, tlat merrat… W kayna wa7ed l-3amaliya f l-compte dyali ma 3reftehach."},{"r":"conseillere","fr":"Je regarde… Un paiement de deux cents euros, hier soir, à l'étranger.","it":"Controllo… Un pagamento di duecento euro, ieri sera, all'estero.","es":"Lo miro… Un pago de doscientos euros, anoche, en el extranjero.","pt":"Vou ver… Um pagamento de duzentos euros, ontem à noite, no estrangeiro.","en":"Let me look… A payment of two hundred euros, last night, abroad.","de":"Ich schaue nach… Eine Zahlung über zweihundert Euro, gestern Abend, im Ausland.","nl":"Even kijken… Een betaling van tweehonderd euro, gisteravond, in het buitenland.","ary":"Daba nchouf… Khlass d mitin euro, lbare7 f l-lil, f l-kharij."},{"r":"toi","fr":"Ce n'est pas moi ! Je voudrais faire opposition sur ma carte.","it":"Non sono stato io! Vorrei bloccare la carta.","es":"¡No he sido yo! Quiero bloquear la tarjeta.","pt":"Não fui eu! Queria cancelar o cartão.","en":"That wasn't me! I'd like to cancel my card.","de":"Das war ich nicht! Ich möchte meine Karte sperren lassen.","nl":"Dat was ik niet! Ik wil mijn pas laten blokkeren.","ary":"Machi ana! Bghit nbloki l-carte dyali."},{"r":"conseillere","fr":"C'est fait. Vous recevrez une nouvelle carte dans cinq jours, sans frais.","it":"Fatto. Riceverà una nuova carta tra cinque giorni, senza spese.","es":"Hecho. Recibirá una tarjeta nueva en cinco días, sin gastos.","pt":"Já está. Recebe um cartão novo dentro de cinco dias, sem custos.","en":"Done. You'll get a new card in five days, free of charge.","de":"Erledigt. Sie bekommen in fünf Tagen eine neue Karte, kostenlos.","nl":"Geregeld. U ontvangt binnen vijf dagen een nieuwe pas, kosteloos.","ary":"Safi. Ghadi tousslek carte jdida men daba khamsa d l-iyyam, bla masarif."}]},"b1u17":{"set":{"fr":"Au garage. Ta voiture fait un bruit bizarre depuis quelques jours.","it":"In officina. Da qualche giorno la tua macchina fa un rumore strano.","es":"En el taller. Tu coche hace un ruido raro desde hace unos días.","pt":"Na oficina. Há uns dias que o teu carro faz um barulho esquisito.","en":"At the garage. Your car has been making a strange noise for a few days.","de":"In der Werkstatt. Dein Auto macht seit ein paar Tagen ein komisches Geräusch.","nl":"Bij de garage. Je auto maakt al een paar dagen een raar geluid.","ary":"F l-garage. T-tomobil dyalek hadi chi iyyam w hiya katdir wa7ed s-sda3 ghrib."},"lines":[{"r":"toi","fr":"Bonjour. Il y a un voyant allumé sur le tableau de bord, et les freins font un drôle de bruit.","it":"Buongiorno. C'è una spia accesa sul cruscotto e i freni fanno un rumore strano.","es":"Buenos días. Hay un testigo encendido en el salpicadero y los frenos hacen un ruido raro.","pt":"Bom dia. Há uma luz acesa no painel e os travões fazem um barulho esquisito.","en":"Hello. There's a warning light on the dashboard, and the brakes are making a funny noise.","de":"Guten Tag. Auf dem Armaturenbrett leuchtet eine Warnlampe, und die Bremsen machen ein komisches Geräusch.","nl":"Goedendag. Er brandt een lampje op het dashboard en de remmen maken een raar geluid.","ary":"Salam. Kayn wa7ed d-daw mcha3el f t-tableau de bord, w l-frinat kaydirou sda3 ghrib."},{"r":"garagiste","fr":"Je vais regarder… Les plaquettes de frein sont usées. Il faut les changer.","it":"Vediamo… Le pastiglie dei freni sono consumate. Bisogna cambiarle.","es":"A ver… Las pastillas de freno están gastadas. Hay que cambiarlas.","pt":"Deixe ver… As pastilhas dos travões estão gastas. É preciso mudá-las.","en":"Let's have a look… The brake pads are worn. They need changing.","de":"Ich schaue mal… Die Bremsbeläge sind abgenutzt. Die müssen gewechselt werden.","nl":"Even kijken… De remblokken zijn versleten. Die moeten vervangen worden.","ary":"Daba nchouf… L-plaquettes d l-frinat tayhin. Khasshom ytbddlou."},{"r":"toi","fr":"D'accord. Vous pouvez me faire un devis ?","it":"D'accordo. Mi può fare un preventivo?","es":"De acuerdo. ¿Me puede hacer un presupuesto?","pt":"Está bem. Pode fazer-me um orçamento?","en":"OK. Can you give me a quote?","de":"In Ordnung. Können Sie mir einen Kostenvoranschlag machen?","nl":"Goed. Kunt u een offerte voor me maken?","ary":"Wakha. T9der t3tini devis?"},{"r":"garagiste","fr":"Cent quatre-vingts euros, avec la vidange. Et votre contrôle technique est dans un mois.","it":"Centottanta euro, con il cambio dell'olio. E la revisione scade tra un mese.","es":"Ciento ochenta euros, con el cambio de aceite. Y la ITV le toca dentro de un mes.","pt":"Cento e oitenta euros, com a mudança de óleo. E a inspeção é daqui a um mês.","en":"A hundred and eighty euros, including the oil change. And your MOT is due in a month.","de":"Hundertachtzig Euro, mit Ölwechsel. Und Ihr TÜV ist in einem Monat fällig.","nl":"Honderdtachtig euro, met olie verversen. En uw APK is over een maand.","ary":"Mya w tmanin euro, m3a l-vidange. W l-visite technique dyalek men daba chher."},{"r":"toi","fr":"Elle sera prête quand ?","it":"Quando sarà pronta?","es":"¿Cuándo estará listo?","pt":"Quando estará pronto?","en":"When will it be ready?","de":"Wann ist es fertig?","nl":"Wanneer is hij klaar?","ary":"Imta tkoun wajda?"},{"r":"garagiste","fr":"Demain en fin d'après-midi. Je vous appelle quand c'est fini.","it":"Domani nel tardo pomeriggio. La chiamo quando ho finito.","es":"Mañana a última hora de la tarde. Le llamo cuando esté.","pt":"Amanhã ao fim da tarde. Ligo-lhe quando estiver pronto.","en":"Tomorrow, late afternoon. I'll call you when it's done.","de":"Morgen am späten Nachmittag. Ich rufe Sie an, wenn es fertig ist.","nl":"Morgen aan het eind van de middag. Ik bel u als hij klaar is.","ary":"Ghedda f l-3chiya. N3ayyet lik mlli nsali."}]},"b1u18":{"set":{"fr":"Chez la vétérinaire, avec ton chien qui ne va pas bien.","it":"Dalla veterinaria, con il tuo cane che non sta bene.","es":"En la veterinaria, con tu perro, que no está bien.","pt":"Na veterinária, com o teu cão, que não está bem.","en":"At the vet's with your dog, who isn't well.","de":"Bei der Tierärztin, mit deinem Hund, dem es nicht gut geht.","nl":"Bij de dierenarts, met je hond die zich niet lekker voelt.","ary":"3nd t-tbiba d l-7ayawanat, m3a l-kelb dyalek lli ma mzyanch."},"lines":[{"r":"veterinaire","fr":"Bonjour ! Qu'est-ce qui ne va pas avec ce beau chien ?","it":"Buongiorno! Che cos'ha questo bel cane?","es":"¡Buenos días! ¿Qué le pasa a este perro tan bonito?","pt":"Bom dia! O que tem este cão tão bonito?","en":"Hello! What's wrong with this lovely dog?","de":"Guten Tag! Was hat denn dieser schöne Hund?","nl":"Goedendag! Wat is er met deze mooie hond?","ary":"Salam! Ach bih had l-kelb z-zwin?"},{"r":"toi","fr":"Il ne mange plus depuis hier, et il boite de la patte arrière.","it":"Non mangia più da ieri e zoppica dalla zampa posteriore.","es":"No come desde ayer y cojea de la pata trasera.","pt":"Não come desde ontem e coxeia da pata de trás.","en":"He hasn't eaten since yesterday, and he's limping on his back leg.","de":"Er frisst seit gestern nicht mehr und humpelt am Hinterbein.","nl":"Hij eet sinds gisteren niet meer en hij loopt mank met zijn achterpoot.","ary":"Ma b9ach kayakol men lbare7, w kay3rej b r-rjel l-lowra."},{"r":"veterinaire","fr":"Voyons ça… Il a une petite blessure à la patte. Ce n'est pas grave.","it":"Vediamo… Ha una piccola ferita alla zampa. Non è grave.","es":"A ver… Tiene una pequeña herida en la pata. No es grave.","pt":"Vamos ver… Tem uma pequena ferida na pata. Não é grave.","en":"Let's see… He has a small wound on his paw. It's nothing serious.","de":"Mal sehen… Er hat eine kleine Wunde an der Pfote. Nicht schlimm.","nl":"Even kijken… Hij heeft een wondje aan zijn poot. Niet ernstig.","ary":"Nchoufou… 3ndo jer7 sghir f r-rjel. Machi khatir."},{"r":"toi","fr":"Ouf ! Et pour la nourriture ?","it":"Meno male! E per il cibo?","es":"¡Uf! ¿Y lo de la comida?","pt":"Ufa! E a comida?","en":"Phew! And what about him not eating?","de":"Puh! Und das mit dem Fressen?","nl":"Pff! En het eten?","ary":"L-7amdoulillah! W l-makla?"},{"r":"veterinaire","fr":"Il a sûrement mal. Je vous donne un médicament. Vous avez son carnet de santé ?","it":"Sicuramente ha dolore. Le do una medicina. Ha il suo libretto sanitario?","es":"Seguro que le duele. Le doy un medicamento. ¿Tiene su cartilla sanitaria?","pt":"Deve ter dores. Vou dar-lhe um medicamento. Tem o boletim sanitário dele?","en":"He's probably in pain. I'll give you some medicine. Do you have his health record?","de":"Er hat bestimmt Schmerzen. Ich gebe Ihnen ein Medikament. Haben Sie seinen Impfpass?","nl":"Hij heeft vast pijn. Ik geef u een medicijn. Heeft u zijn dierenpaspoort?","ary":"Akid kayderro. Ghadi n3tik dwa. 3ndek l-karni s-si77i dyalo?"},{"r":"toi","fr":"Oui, le voici. Il a aussi besoin d'un vermifuge, je crois.","it":"Sì, eccolo. Credo che abbia bisogno anche del vermifugo.","es":"Sí, aquí está. Creo que también necesita desparasitarlo.","pt":"Sim, aqui está. Acho que também precisa de ser desparasitado.","en":"Yes, here it is. I think he also needs worming.","de":"Ja, hier. Ich glaube, er muss auch entwurmt werden.","nl":"Ja, alstublieft. Ik denk dat hij ook ontwormd moet worden.","ary":"Iyeh, ha howa. Kandenn khasso 7tta dwa d d-doud."},{"r":"veterinaire","fr":"Je le note. Revenez dans une semaine s'il boite encore.","it":"Lo segno. Torni tra una settimana se zoppica ancora.","es":"Lo apunto. Vuelva dentro de una semana si sigue cojeando.","pt":"Fica anotado. Volte daqui a uma semana se ainda coxear.","en":"I'll make a note. Come back in a week if he's still limping.","de":"Ich notiere es. Kommen Sie in einer Woche wieder, wenn er noch humpelt.","nl":"Ik noteer het. Kom over een week terug als hij nog mank loopt.","ary":"Ktebtha. Rje3 men daba simana ila mazal kay3rej."}]},"b1u19":{"set":{"fr":"En voiture, en route pour les vacances. Ta petite sœur est à l'arrière.","it":"In macchina, si parte per le vacanze. La tua sorellina è dietro.","es":"En el coche, de camino a las vacaciones. Tu hermanita va detrás.","pt":"No carro, a caminho das férias. A tua irmã mais nova vai atrás.","en":"In the car on the way to your holiday. Your little sister is in the back.","de":"Im Auto auf dem Weg in den Urlaub. Deine kleine Schwester sitzt hinten.","nl":"In de auto, op weg naar de vakantie. Je zusje zit achterin.","ary":"F t-tomobil, f t-tri9 l l-3otla. Khtek s-sghira gals f l-lour."},"lines":[{"r":"enfant","fr":"On arrive quand ?","it":"Quando arriviamo?","es":"¿Cuándo llegamos?","pt":"Quando é que chegamos?","en":"Are we there yet?","de":"Wann sind wir da?","nl":"Wanneer zijn we er?","ary":"Imta ghadi nwslou?"},{"r":"pere","fr":"Dans deux heures. Tu as déjà demandé il y a cinq minutes !","it":"Tra due ore. L'hai già chiesto cinque minuti fa!","es":"Dentro de dos horas. ¡Ya lo has preguntado hace cinco minutos!","pt":"Daqui a duas horas. Já perguntaste há cinco minutos!","en":"In two hours. You asked five minutes ago!","de":"In zwei Stunden. Das hast du vor fünf Minuten schon gefragt!","nl":"Over twee uur. Dat vroeg je vijf minuten geleden ook al!","ary":"Men daba jouj s3at. Rah sowwelti 9bel khems d9aye9!"},{"r":"enfant","fr":"Je m'ennuie… Il y a une piscine pour les petits, à la location ?","it":"Mi annoio… Nella casa delle vacanze c'è una piscina per i piccoli?","es":"Me aburro… ¿En el apartamento hay piscina para niños?","pt":"Estou aborrecida… A casa de férias tem piscina para os pequenos?","en":"I'm bored… Is there a kids' pool at the holiday house?","de":"Mir ist langweilig… Gibt es in der Ferienwohnung ein Kinderbecken?","nl":"Ik verveel me… Heeft het vakantiehuis een kinderbad?","ary":"Mallit… Kayna piscine d s-sghar f d-dar d l-3otla?"},{"r":"toi","fr":"Oui, et une plage juste à côté. Et demain, on va au parc d'attractions !","it":"Sì, e una spiaggia proprio vicino. E domani andiamo al parco divertimenti!","es":"Sí, y una playa justo al lado. ¡Y mañana vamos al parque de atracciones!","pt":"Sim, e uma praia mesmo ao lado. E amanhã vamos ao parque de diversões!","en":"Yes, and a beach right next to it. And tomorrow we're going to the theme park!","de":"Ja, und ein Strand direkt nebenan. Und morgen gehen wir in den Freizeitpark!","nl":"Ja, en een strand vlak naast de deur. En morgen gaan we naar het pretpark!","ary":"Iyeh, w l-b7er 7daha. W ghedda ghadi nmchiw l l-parc d l-al3ab!"},{"r":"pere","fr":"Oh non… On a oublié le chargeur de la tablette !","it":"Oh no… Abbiamo dimenticato il caricatore del tablet!","es":"¡Oh, no… Nos hemos olvidado el cargador de la tableta!","pt":"Oh não… Esquecemo-nos do carregador do tablet!","en":"Oh no… We've forgotten the tablet charger!","de":"Oh nein… Wir haben das Ladekabel vom Tablet vergessen!","nl":"O nee… We zijn de oplader van de tablet vergeten!","ary":"Oh la… Nsina l-chargeur d t-tablette!"},{"r":"toi","fr":"Ce n'est pas grave. On joue à un jeu : chacun choisit une activité pour la semaine.","it":"Non fa niente. Facciamo un gioco: ognuno sceglie un'attività per la settimana.","es":"No pasa nada. Jugamos a algo: cada uno elige una actividad para la semana.","pt":"Não faz mal. Vamos jogar um jogo: cada um escolhe uma atividade para a semana.","en":"Never mind. Let's play a game: everyone picks an activity for the week.","de":"Nicht schlimm. Wir spielen ein Spiel: Jeder sucht sich eine Aktivität für die Woche aus.","nl":"Geeft niks. We doen een spelletje: iedereen kiest een activiteit voor de week.","ary":"Machi mochkil. Nl3bou wa7ed l-lo3ba: koll wa7ed ykhtar nachat l s-simana."}]},"b1u20":{"set":{"fr":"À la bibliothèque de l'université, en pleine période d'examens.","it":"Nella biblioteca dell'università, in piena sessione d'esami.","es":"En la biblioteca de la universidad, en plena época de exámenes.","pt":"Na biblioteca da universidade, em plena época de exames.","en":"In the university library, right in the middle of exams.","de":"In der Unibibliothek, mitten in der Prüfungszeit.","nl":"In de universiteitsbibliotheek, midden in de tentamenperiode.","ary":"F l-maktaba d l-jami3a, f wesst l-imti7anat."},"lines":[{"r":"ami","fr":"J'ai séché le cours ce matin… Tu peux me passer tes notes ?","it":"Stamattina ho saltato la lezione… Mi passi i tuoi appunti?","es":"Esta mañana me salté la clase… ¿Me pasas tus apuntes?","pt":"Hoje de manhã faltei à aula… Passas-me os teus apontamentos?","en":"I skipped the lecture this morning… Can you lend me your notes?","de":"Ich habe heute Morgen die Vorlesung geschwänzt… Kannst du mir deine Notizen geben?","nl":"Ik heb vanochtend het college gespijbeld… Mag ik jouw aantekeningen?","ary":"Had s-sba7 ma mchitch l d-dars… T9der t3tini n-notes dyalek?"},{"r":"toi","fr":"D'accord, mais c'est la dernière fois ! Les examens sont la semaine prochaine.","it":"Va bene, ma è l'ultima volta! Gli esami sono la settimana prossima.","es":"Vale, pero es la última vez. ¡Los exámenes son la semana que viene!","pt":"Está bem, mas é a última vez! Os exames são na próxima semana.","en":"OK, but it's the last time! Exams are next week.","de":"Okay, aber das ist das letzte Mal! Die Prüfungen sind nächste Woche.","nl":"Oké, maar het is de laatste keer! De tentamens zijn volgende week.","ary":"Wakha, walakin hadi akhir merra! L-imti7anat s-simana j-jaya."},{"r":"ami","fr":"Je sais. Je révise toute la nuit depuis lundi.","it":"Lo so. Studio tutta la notte da lunedì.","es":"Lo sé. Llevo estudiando toda la noche desde el lunes.","pt":"Eu sei. Estudo a noite toda desde segunda-feira.","en":"I know. I've been revising all night since Monday.","de":"Ich weiß. Seit Montag lerne ich die ganze Nacht.","nl":"Ik weet het. Ik studeer sinds maandag de hele nacht door.","ary":"3arf. Men nhar t-tnin w ana kanrajje3 l-lil kamel."},{"r":"toi","fr":"Tu devrais dormir un peu, sinon tu ne retiendras rien.","it":"Dovresti dormire un po', altrimenti non ti ricorderai niente.","es":"Deberías dormir un poco, si no, no te acordarás de nada.","pt":"Devias dormir um pouco, senão não vais reter nada.","en":"You should get some sleep, or you won't remember a thing.","de":"Du solltest ein bisschen schlafen, sonst behältst du nichts.","nl":"Je moet wat slapen, anders onthoud je niks.","ary":"Khassek tn3es chwiya, wla ma ghadi tchedd walou."},{"r":"ami","fr":"Tu as raison. Et toi, ton mémoire, ça avance ?","it":"Hai ragione. E tu, la tesi come va?","es":"Tienes razón. ¿Y tú, qué tal el trabajo de fin de grado?","pt":"Tens razão. E tu, a tese está a avançar?","en":"You're right. And how's your dissertation going?","de":"Du hast recht. Und du, wie läuft deine Abschlussarbeit?","nl":"Je hebt gelijk. En jij, schiet je scriptie op?","ary":"3ndek l-7e99. W nta, l-mémoire dyalek ki dayr?"},{"r":"toi","fr":"Doucement… Il est à rendre en juin. Mais si je valide mon semestre, je pars en Erasmus !","it":"Piano piano… Va consegnata a giugno. Ma se supero il semestre, parto in Erasmus!","es":"Poco a poco… Hay que entregarlo en junio. Pero si apruebo el semestre, ¡me voy de Erasmus!","pt":"Devagar… É para entregar em junho. Mas se fizer o semestre, vou de Erasmus!","en":"Slowly… It's due in June. But if I pass the semester, I'm going on Erasmus!","de":"Langsam… Abgabe ist im Juni. Aber wenn ich das Semester bestehe, gehe ich mit Erasmus ins Ausland!","nl":"Langzaam… Hij moet in juni af. Maar als ik mijn semester haal, ga ik op Erasmus!","ary":"B chwiya… Khassni nsallmou f younyou. Walakin ila nje7t f s-semestre, ghadi nmchi f Erasmus!"}]},"b1u21":{"set":{"fr":"Au bureau de poste, avec un colis sous le bras.","it":"All'ufficio postale, con un pacco sotto il braccio.","es":"En la oficina de correos, con un paquete bajo el brazo.","pt":"Nos correios, com uma encomenda debaixo do braço.","en":"At the post office, with a parcel under your arm.","de":"Auf der Post, mit einem Paket unter dem Arm.","nl":"Op het postkantoor, met een pakket onder je arm.","ary":"F l-bosta, w l-colis ta7t dra3ek."},"lines":[{"r":"toi","fr":"Bonjour, je voudrais envoyer ce colis à l'étranger.","it":"Buongiorno, vorrei spedire questo pacco all'estero.","es":"Buenos días, quería enviar este paquete al extranjero.","pt":"Bom dia, queria enviar esta encomenda para o estrangeiro.","en":"Hello, I'd like to send this parcel abroad.","de":"Guten Tag, ich möchte dieses Paket ins Ausland schicken.","nl":"Goedendag, ik wil dit pakket naar het buitenland sturen.","ary":"Salam, bghit nsifet had l-colis l l-kharij."},{"r":"guichetier","fr":"En envoi normal ou en recommandé ?","it":"Spedizione normale o raccomandata?","es":"¿Envío normal o certificado?","pt":"Envio normal ou registado?","en":"Standard or recorded delivery?","de":"Normal oder als Einschreiben?","nl":"Gewoon of aangetekend?","ary":"3adi wla recommandé?"},{"r":"toi","fr":"En recommandé. Il arrivera sous combien de jours ?","it":"Raccomandata. In quanti giorni arriverà?","es":"Certificado. ¿En cuántos días llegará?","pt":"Registado. Chega em quantos dias?","en":"Recorded. How many days will it take?","de":"Als Einschreiben. In wie vielen Tagen kommt es an?","nl":"Aangetekend. Binnen hoeveel dagen komt het aan?","ary":"Recommandé. F ch7al d l-iyyam ghadi ywsel?"},{"r":"guichetier","fr":"Entre cinq et sept jours. Voici votre numéro de suivi.","it":"Tra cinque e sette giorni. Ecco il suo numero di tracciamento.","es":"Entre cinco y siete días. Aquí tiene su número de seguimiento.","pt":"Entre cinco e sete dias. Aqui está o seu número de seguimento.","en":"Between five and seven days. Here's your tracking number.","de":"Zwischen fünf und sieben Tagen. Hier ist Ihre Sendungsnummer.","nl":"Tussen vijf en zeven dagen. Hier is uw trackingnummer.","ary":"Bin khamsa w seb3a d l-iyyam. Hak r-ra9m d t-tatabbo3."},{"r":"toi","fr":"Merci. Autre chose : le livreur est passé hier, mais je n'étais pas là.","it":"Grazie. Un'altra cosa: ieri è passato il corriere, ma non ero in casa.","es":"Gracias. Otra cosa: ayer pasó el repartidor, pero yo no estaba.","pt":"Obrigado. Outra coisa: o estafeta passou ontem, mas eu não estava.","en":"Thanks. Another thing: the courier came yesterday, but I wasn't in.","de":"Danke. Noch etwas: Der Paketbote war gestern da, aber ich war nicht zu Hause.","nl":"Dank u. Nog iets: de bezorger is gisteren langsgekomen, maar ik was niet thuis.","ary":"Chokran. W chi 7aja khra: l-livreur ja lbare7, walakin ma kontch f d-dar."},{"r":"guichetier","fr":"Votre colis est sûrement au point relais. Vous avez l'avis de passage ?","it":"Il pacco sarà al punto di ritiro. Ha l'avviso di passaggio?","es":"Seguro que su paquete está en el punto de recogida. ¿Tiene el aviso de entrega?","pt":"A encomenda deve estar no ponto de recolha. Tem o aviso de passagem?","en":"Your parcel is probably at the pick-up point. Do you have the delivery notice?","de":"Ihr Paket ist bestimmt in der Paketstation. Haben Sie die Benachrichtigungskarte?","nl":"Uw pakket ligt vast bij het afhaalpunt. Heeft u het afwezigheidsbericht?","ary":"Akid l-colis dyalek f l-point relais. 3ndek l-woura d l-ikhtar?"}]},"b1u22":{"set":{"fr":"Ton amie t'apprend une recette de son pays.","it":"La tua amica ti insegna una ricetta del suo paese.","es":"Tu amiga te enseña una receta de su país.","pt":"A tua amiga ensina-te uma receita do país dela.","en":"Your friend is teaching you a recipe from her country.","de":"Deine Freundin bringt dir ein Rezept aus ihrem Land bei.","nl":"Je vriendin leert je een recept uit haar land.","ary":"Sa7btek kat3allmek wa7ed l-wasfa men bladha."},"lines":[{"r":"amie","fr":"D'abord, fais revenir les oignons dans l'huile, à feu doux.","it":"Prima fai rosolare le cipolle nell'olio, a fuoco basso.","es":"Primero, sofríe la cebolla en el aceite, a fuego lento.","pt":"Primeiro, aloura as cebolas no azeite, em lume brando.","en":"First, fry the onions gently in the oil over a low heat.","de":"Zuerst die Zwiebeln im Öl bei schwacher Hitze anbraten.","nl":"Fruit eerst de uien in de olie op een laag vuur.","ary":"L-lowel, 7emmer l-besla f z-zit 3la nar khfifa."},{"r":"toi","fr":"Comme ça ? Et j'ajoute les épices maintenant ?","it":"Così? E aggiungo le spezie adesso?","es":"¿Así? ¿Y añado las especias ahora?","pt":"Assim? E junto as especiarias agora?","en":"Like this? Do I add the spices now?","de":"So? Und gebe ich jetzt die Gewürze dazu?","nl":"Zo? En doe ik de kruiden er nu bij?","ary":"Hakka? W nzid l-3tria daba?"},{"r":"amie","fr":"Oui, mais juste une pincée de piment : c'est très épicé, attention !","it":"Sì, ma solo un pizzico di peperoncino: è molto piccante, attento!","es":"Sí, pero solo una pizca de guindilla: ¡pica mucho, cuidado!","pt":"Sim, mas só uma pitada de malagueta: é muito picante, cuidado!","en":"Yes, but just a pinch of chilli: it's very hot, careful!","de":"Ja, aber nur eine Prise Chili: Das ist sehr scharf, Vorsicht!","nl":"Ja, maar maar een snufje chili: het is erg pittig, pas op!","ary":"Iyeh, walakin ghir chwiya d l-flfla l-7arra: 7arra bezzaf, rdd balek!"},{"r":"toi","fr":"Et la viande ?","it":"E la carne?","es":"¿Y la carne?","pt":"E a carne?","en":"And the meat?","de":"Und das Fleisch?","nl":"En het vlees?","ary":"W l-l7em?"},{"r":"amie","fr":"Je l'ai fait mariner hier soir. On la met et on laisse mijoter une heure.","it":"L'ho fatta marinare ieri sera. La mettiamo dentro e lasciamo cuocere piano per un'ora.","es":"La dejé marinando anoche. La echamos y la dejamos guisar a fuego lento una hora.","pt":"Deixei-a a marinar ontem à noite. Pomo-la e deixamos estufar uma hora.","en":"I marinated it last night. We put it in and let it simmer for an hour.","de":"Ich habe es gestern Abend mariniert. Wir geben es dazu und lassen es eine Stunde schmoren.","nl":"Ik heb het gisteravond gemarineerd. We doen het erbij en laten het een uur sudderen.","ary":"Khellito ychreb t-tchermila lbare7 f l-lil. Nzidouh w nkhelliweh ytyab sa3a 3la nar khfifa."},{"r":"toi","fr":"Une heure ? J'ai déjà faim… Pendant ce temps, je prépare le riz ?","it":"Un'ora? Ho già fame… Intanto preparo il riso?","es":"¿Una hora? Ya tengo hambre… Mientras tanto, ¿preparo el arroz?","pt":"Uma hora? Já tenho fome… Entretanto, preparo o arroz?","en":"An hour? I'm already hungry… Shall I make the rice in the meantime?","de":"Eine Stunde? Ich habe jetzt schon Hunger… Soll ich in der Zeit den Reis machen?","nl":"Een uur? Ik heb nu al honger… Zal ik ondertussen de rijst maken?","ary":"Sa3a? Rani ji3an deja… F had l-weqt, nwejjed r-rouz?"}]},"b1u23":{"set":{"fr":"Premier soir de ton job d'été dans un bar. Le patron t'explique tout.","it":"Prima sera del tuo lavoretto estivo in un bar. Il titolare ti spiega tutto.","es":"Primera noche de tu trabajo de verano en un bar. El jefe te lo explica todo.","pt":"Primeira noite do teu trabalho de verão num bar. O patrão explica-te tudo.","en":"First evening of your summer job in a bar. The boss explains everything.","de":"Erster Abend deines Sommerjobs in einer Bar. Der Chef erklärt dir alles.","nl":"Eerste avond van je zomerbaantje in een bar. De baas legt alles uit.","ary":"Awwel lila f l-khedma d s-sif f wa7ed l-bar. L-patron kaychre7 lik koulchi."},"lines":[{"r":"patron","fr":"Bienvenue ! Tu as déjà travaillé dans un bar ?","it":"Benvenuto! Hai già lavorato in un bar?","es":"¡Bienvenido! ¿Ya has trabajado en un bar?","pt":"Bem-vindo! Já trabalhaste num bar?","en":"Welcome! Have you worked in a bar before?","de":"Willkommen! Hast du schon mal in einer Bar gearbeitet?","nl":"Welkom! Heb je al eens in een bar gewerkt?","ary":"Merhba! Wach deja khdemti f chi bar?"},{"r":"toi","fr":"Non, mais j'ai fait du baby-sitting, et j'apprends vite.","it":"No, ma ho fatto la babysitter e imparo in fretta.","es":"No, pero he hecho de canguro y aprendo rápido.","pt":"Não, mas já fiz babysitting e aprendo depressa.","en":"No, but I've done babysitting, and I learn fast.","de":"Nein, aber ich habe als Babysitter gearbeitet und lerne schnell.","nl":"Nee, maar ik heb opgepast en ik leer snel.","ary":"La, walakin khdemt baby-sitting, w kant3allem bezzerba."},{"r":"patron","fr":"Parfait. Tu commences à dix-huit heures et tu finis à minuit. Tu es payé à l'heure.","it":"Perfetto. Cominci alle diciotto e finisci a mezzanotte. Sei pagato a ore.","es":"Perfecto. Empiezas a las seis de la tarde y terminas a medianoche. Cobras por horas.","pt":"Perfeito. Começas às seis da tarde e acabas à meia-noite. És pago à hora.","en":"Perfect. You start at six and finish at midnight. You're paid by the hour.","de":"Perfekt. Du fängst um achtzehn Uhr an und hörst um Mitternacht auf. Du wirst stundenweise bezahlt.","nl":"Prima. Je begint om zes uur en je stopt om middernacht. Je wordt per uur betaald.","ary":"Mzyan. Katbda m3a s-stta d l-3chiya w katsali f ness l-lil. Katkhelles b s-sa3a."},{"r":"toi","fr":"D'accord. Et les pourboires ?","it":"D'accordo. E le mance?","es":"Vale. ¿Y las propinas?","pt":"Está bem. E as gorjetas?","en":"OK. And what about tips?","de":"In Ordnung. Und das Trinkgeld?","nl":"Oké. En de fooi?","ary":"Wakha. W l-pourboire?"},{"r":"patron","fr":"On les partage entre tout le monde à la fin de la semaine. Ça aide bien !","it":"Le dividiamo tra tutti a fine settimana. Aiutano parecchio!","es":"Las repartimos entre todos al final de la semana. ¡Ayudan bastante!","pt":"Dividimo-las por todos no fim da semana. Dão uma boa ajuda!","en":"We share them between everyone at the end of the week. They help a lot!","de":"Das teilen wir am Ende der Woche unter allen auf. Das hilft ganz schön!","nl":"Die verdelen we aan het eind van de week onder iedereen. Dat scheelt een hoop!","ary":"Kan9essmouh 3la koulchi f l-akhir d s-simana. Kay3awen bezzaf!"},{"r":"toi","fr":"Super. Avec ça, je pourrai payer mes études.","it":"Ottimo. Così potrò pagarmi gli studi.","es":"Genial. Así podré pagarme los estudios.","pt":"Ótimo. Assim vou poder pagar os estudos.","en":"Great. With that, I'll be able to pay for my studies.","de":"Super. Damit kann ich mein Studium bezahlen.","nl":"Top. Daarmee kan ik mijn studie betalen.","ary":"Zwin. B hadchi ghadi n9der nkhelles 3la 9raiti."}]}}});
